/** Searchable select built on Popover and Command: type to filter a long list, pick one value or several, and see multiple picks as removable badges. */
import * as React from "react";
import { Check, ChevronDown, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { useFormatters, useT } from "@/lib/i18n";
import { Badge } from "@/components/ui/badge";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import { Popover, PopoverAnchor, PopoverContent, PopoverTrigger } from "@/components/ui/popover";

export interface ComboboxOption {
  value: string;
  label: string;
  disabled?: boolean;
  /** Extra search terms that match the option without being shown, such as a code or an alias. */
  keywords?: string[];
}

interface ComboboxBaseProps extends Omit<
  React.ComponentProps<"button">,
  "value" | "defaultValue" | "onChange" | "children" | "type" | "role"
> {
  options: ComboboxOption[];
  /** Shown in the trigger while nothing is selected. */
  placeholder?: React.ReactNode;
  /** Placeholder of the search field inside the list. */
  searchPlaceholder?: string;
  /** Shown in the list when the search matches nothing. */
  emptyText?: React.ReactNode;
  /** With `multiple`, how many badges to show before collapsing to an "n selected" summary. */
  maxBadges?: number;
  /** Classes for the `role="combobox"` button. */
  triggerClassName?: string;
  /** Classes for the floating list surface. */
  contentClassName?: string;
  /** Called when the list opens or closes. */
  onOpenChange?: (open: boolean) => void;
}

export interface ComboboxSingleProps extends ComboboxBaseProps {
  multiple?: false;
  value?: string;
  defaultValue?: string;
  /** Receives the new value, or `""` when the selected option is picked again to clear it. */
  onValueChange?: (value: string) => void;
}

export interface ComboboxMultipleProps extends ComboboxBaseProps {
  multiple: true;
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
}

export type ComboboxProps = ComboboxSingleProps | ComboboxMultipleProps;

function toArray(value: string | string[] | undefined): string[] {
  if (value === undefined || value === "") return [];
  return Array.isArray(value) ? value : [value];
}

/** The field box, kept class-for-class in step with SelectTrigger so the two sit side by side. */
const fieldBase = [
  "flex h-(--control-h-md) w-full items-center gap-2 rounded-input border border-input bg-transparent pe-2 text-sm text-foreground",
  "transition-[color,box-shadow,border-color] duration-(--duration-fast) ease-standard outline-none",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0",
  "dark:bg-input/20",
];

function Combobox(props: ComboboxProps) {
  const {
    options,
    multiple = false,
    value: valueProp,
    defaultValue,
    onValueChange,
    placeholder: placeholderProp,
    searchPlaceholder: searchPlaceholderProp,
    emptyText: emptyTextProp,
    maxBadges = 2,
    className,
    triggerClassName,
    contentClassName,
    onOpenChange,
    onKeyDown,
    disabled,
    name,
    ...triggerProps
  } = props;

  const t = useT();
  const { list } = useFormatters();
  const placeholder = placeholderProp ?? t("combobox.placeholder");
  const searchPlaceholder = searchPlaceholderProp ?? t("combobox.searchPlaceholder");
  const emptyText = emptyTextProp ?? t("combobox.empty");

  const contentId = `${React.useId()}-content`;
  const controlRef = React.useRef<HTMLDivElement>(null);
  const [open, setOpenState] = React.useState(false);
  const [search, setSearch] = React.useState("");
  const [uncontrolled, setUncontrolled] = React.useState<string[]>(() => toArray(defaultValue));
  const selected = valueProp !== undefined ? toArray(valueProp) : uncontrolled;

  const byValue = React.useMemo(
    () => new Map(options.map((option) => [option.value, option])),
    [options],
  );
  const labelOf = (value: string) => byValue.get(value)?.label ?? value;

  const setOpen = (next: boolean) => {
    setOpenState(next);
    // A reopened list starts from the full set rather than the last query.
    if (!next) setSearch("");
    onOpenChange?.(next);
  };

  const commit = (next: string[]) => {
    if (valueProp === undefined) setUncontrolled(next);
    if (multiple) (onValueChange as ((value: string[]) => void) | undefined)?.(next);
    else (onValueChange as ((value: string) => void) | undefined)?.(next[0] ?? "");
  };

  const toggle = (value: string) => {
    if (multiple) {
      commit(selected.includes(value) ? selected.filter((v) => v !== value) : [...selected, value]);
      return;
    }
    commit(selected[0] === value ? [] : [value]);
    setOpen(false);
  };

  const handleTriggerKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented || open || disabled) return;
    // The arrow keys open a closed combobox, as they do a native select.
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      setOpen(true);
    }
  };

  const invalid = triggerProps["aria-invalid"] === true || triggerProps["aria-invalid"] === "true";
  const isEmpty = selected.length === 0;
  const collapsed = multiple && selected.length > maxBadges;
  const showBadges = multiple && !isEmpty && !collapsed;

  let valueText: React.ReactNode;
  if (isEmpty) valueText = placeholder;
  else if (!multiple) valueText = labelOf(selected[0] ?? "");
  else if (collapsed) valueText = t("combobox.selectedCount", { count: selected.length });
  // The badges carry the value visually; the button still needs it as text so
  // a screen reader announces what is selected, not just the field's name.
  else valueText = <span className="sr-only">{list.format(selected.map(labelOf))}</span>;

  const trigger = (
    <PopoverTrigger asChild>
      <button
        type="button"
        role="combobox"
        aria-expanded={open}
        // Only while the popup exists, so the reference never dangles.
        aria-controls={open ? contentId : undefined}
        data-slot="combobox-trigger"
        data-placeholder={isEmpty ? "" : undefined}
        disabled={disabled}
        className={cn(
          multiple
            ? [
                "flex h-full min-w-0 flex-1 items-center gap-2 ps-1.5 text-start outline-none",
                "data-[placeholder]:text-muted-foreground disabled:cursor-not-allowed",
              ]
            : [
                fieldBase,
                "ps-3 text-start",
                "data-[placeholder]:text-muted-foreground",
                "focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/40",
                "aria-invalid:border-destructive aria-invalid:ring-2 aria-invalid:ring-destructive/30",
                "disabled:cursor-not-allowed disabled:opacity-50",
              ],
          triggerClassName,
          !multiple && className,
        )}
        {...triggerProps}
        onKeyDown={handleTriggerKeyDown}
      >
        <span data-slot="combobox-value" className="min-w-0 flex-1 truncate">
          {valueText}
        </span>
        <ChevronDown aria-hidden="true" className="size-4 opacity-50" />
      </button>
    </PopoverTrigger>
  );

  return (
    <Popover open={open} onOpenChange={setOpen}>
      {multiple ? (
        <PopoverAnchor asChild>
          <div
            ref={controlRef}
            data-slot="combobox-control"
            data-invalid={invalid || undefined}
            data-disabled={disabled || undefined}
            className={cn(
              fieldBase,
              "gap-1 overflow-hidden ps-1.5",
              "has-[[data-slot=combobox-trigger]:focus-visible]:border-ring has-[[data-slot=combobox-trigger]:focus-visible]:ring-2 has-[[data-slot=combobox-trigger]:focus-visible]:ring-ring/40",
              "data-[invalid]:border-destructive data-[invalid]:ring-2 data-[invalid]:ring-destructive/30",
              "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
              className,
            )}
          >
            {showBadges
              ? selected.map((value) => {
                  const label = labelOf(value);
                  return (
                    <Badge
                      key={value}
                      variant="secondary"
                      data-slot="combobox-badge"
                      className="min-w-0 max-w-32 shrink pe-0.5"
                    >
                      <span data-slot="combobox-badge-label" className="truncate">
                        {label}
                      </span>
                      <button
                        type="button"
                        data-slot="combobox-badge-remove"
                        aria-label={t("combobox.remove", { label })}
                        disabled={disabled}
                        onClick={() => commit(selected.filter((v) => v !== value))}
                        className={cn(
                          "inline-flex shrink-0 items-center justify-center rounded-badge p-0.5 opacity-70 outline-none",
                          "transition-[opacity,background-color] duration-(--duration-fast) ease-standard",
                          "hover:bg-foreground/10 hover:opacity-100",
                          "focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-ring",
                          "disabled:pointer-events-none",
                        )}
                      >
                        <X aria-hidden="true" className="size-3" />
                      </button>
                    </Badge>
                  );
                })
              : null}
            {trigger}
          </div>
        </PopoverAnchor>
      ) : (
        trigger
      )}

      {name
        ? (multiple ? selected : [selected[0] ?? ""]).map((value, index) => (
            <input
              key={`${index}-${value}`}
              type="hidden"
              data-slot="combobox-input"
              name={name}
              value={value}
            />
          ))
        : null}

      <PopoverContent
        id={contentId}
        data-slot="combobox-content"
        align="start"
        aria-label={triggerProps["aria-label"] ?? t("combobox.listLabel")}
        className={cn("w-(--radix-popover-trigger-width) min-w-48 p-0", contentClassName)}
        // Removing a badge while the list is open should not close the list.
        onInteractOutside={(event) => {
          if (controlRef.current?.contains(event.target as Node)) event.preventDefault();
        }}
      >
        <Command
          label={t("combobox.searchLabel")}
          // Start the keyboard cursor on the current choice, as a select does.
          defaultValue={multiple ? undefined : selected[0]}
        >
          <CommandInput placeholder={searchPlaceholder} value={search} onValueChange={setSearch} />
          <CommandList label={t("combobox.listLabel")} aria-multiselectable={multiple || undefined}>
            <CommandEmpty>{emptyText}</CommandEmpty>
            <CommandGroup>
              {options.map((option) => {
                const isSelected = selected.includes(option.value);
                return (
                  <CommandItem
                    key={option.value}
                    value={option.value}
                    keywords={[option.label, ...(option.keywords ?? [])]}
                    disabled={option.disabled}
                    onSelect={() => toggle(option.value)}
                    // cmdk spends aria-selected on the keyboard cursor, so the
                    // chosen state is exposed as aria-checked instead.
                    aria-checked={isSelected}
                    data-checked={isSelected}
                    className="pe-8"
                  >
                    <span className="truncate">{option.label}</span>
                    <span className="absolute end-2 flex size-3.5 items-center justify-center">
                      <Check
                        aria-hidden="true"
                        className={cn("size-4", isSelected ? "opacity-100" : "opacity-0")}
                      />
                    </span>
                  </CommandItem>
                );
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

export { Combobox };

"use client";

/** Searchable command palette on cmdk, usable inline or inside a dialog as a spotlight-style launcher. */
import * as React from "react";
import { Search } from "lucide-react";
import { Command as CommandPrimitive } from "cmdk";
import { cn } from "@/lib/utils";
import { useT } from "@/lib/i18n";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";

export type CommandProps = React.ComponentProps<typeof CommandPrimitive>;

function Command({ className, ...props }: CommandProps) {
  return (
    <CommandPrimitive
      data-slot="command"
      className={cn(
        "flex size-full flex-col overflow-hidden rounded-card bg-popover text-popover-foreground",
        className,
      )}
      {...props}
    />
  );
}

export interface CommandDialogProps extends React.ComponentProps<typeof Dialog> {
  /** Accessible name for the palette. Visually hidden unless `showHeader` is set. */
  title?: string;
  /** Accessible description for the palette. */
  description?: string;
  /** Show the title and description above the input instead of only to screen readers. */
  showHeader?: boolean;
  /** Classes for the dialog surface. */
  className?: string;
}

function CommandDialog({
  title: titleProp,
  description: descriptionProp,
  showHeader = false,
  className,
  children,
  ...props
}: CommandDialogProps) {
  const t = useT();
  const title = titleProp ?? t("command.title");
  const description = descriptionProp ?? t("command.description");

  return (
    <Dialog {...props}>
      <DialogContent
        data-slot="command-dialog"
        showCloseButton={false}
        className={cn("overflow-hidden p-0", className)}
      >
        <DialogHeader className={cn(showHeader ? "px-4 pt-4" : "sr-only")}>
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>{description}</DialogDescription>
        </DialogHeader>
        <Command
          className={cn(
            "[&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:font-medium [&_[cmdk-group-heading]]:text-muted-foreground",
            "[&_[cmdk-group]]:px-2 [&_[cmdk-group]:not([hidden])_~[cmdk-group]]:pt-0",
            "[&_[cmdk-input-wrapper]_svg]:size-5 [&_[cmdk-input]]:h-12",
            "[&_[cmdk-item]]:px-2 [&_[cmdk-item]]:py-3 [&_[cmdk-item]_svg]:size-5",
          )}
        >
          {children}
        </Command>
      </DialogContent>
    </Dialog>
  );
}

function CommandInput({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Input>) {
  return (
    <div data-slot="command-input-wrapper" className="flex items-center gap-2 border-b px-3">
      <Search className="size-4 shrink-0 text-muted-foreground" />
      <CommandPrimitive.Input
        data-slot="command-input"
        className={cn(
          "flex h-10 w-full rounded-md bg-transparent py-3 text-sm outline-none",
          "placeholder:text-muted-foreground",
          "disabled:cursor-not-allowed disabled:opacity-50",
          className,
        )}
        {...props}
      />
    </div>
  );
}

function CommandList({ className, ...props }: React.ComponentProps<typeof CommandPrimitive.List>) {
  return (
    <CommandPrimitive.List
      data-slot="command-list"
      className={cn("max-h-80 scroll-py-1 overflow-y-auto overflow-x-hidden", className)}
      {...props}
    />
  );
}

function CommandEmpty(props: React.ComponentProps<typeof CommandPrimitive.Empty>) {
  return (
    <CommandPrimitive.Empty
      data-slot="command-empty"
      className="py-6 text-center text-sm text-muted-foreground"
      {...props}
    />
  );
}

function CommandGroup({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Group>) {
  return (
    <CommandPrimitive.Group
      data-slot="command-group"
      className={cn(
        "overflow-hidden p-1 text-foreground",
        "[&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5",
        "[&_[cmdk-group-heading]]:text-xs [&_[cmdk-group-heading]]:font-medium [&_[cmdk-group-heading]]:text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

function CommandItem({ className, ...props }: React.ComponentProps<typeof CommandPrimitive.Item>) {
  return (
    <CommandPrimitive.Item
      data-slot="command-item"
      className={cn(
        "relative flex cursor-default select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none",
        "data-[selected=true]:bg-accent data-[selected=true]:text-accent-foreground",
        "data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50",
        "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
        className,
      )}
      {...props}
    />
  );
}

function CommandSeparator({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Separator>) {
  return (
    <CommandPrimitive.Separator
      data-slot="command-separator"
      className={cn("-mx-1 h-px bg-border", className)}
      {...props}
    />
  );
}

function CommandShortcut({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="command-shortcut"
      className={cn("ms-auto text-xs tracking-widest text-muted-foreground", className)}
      {...props}
    />
  );
}

export {
  Command,
  CommandDialog,
  CommandInput,
  CommandList,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandSeparator,
  CommandShortcut,
};

"use client";

/** Menu raised by a right-click or long-press on its trigger area, with the same anatomy as the dropdown menu. */
import * as React from "react";
import { Check, ChevronRight, Circle } from "lucide-react";
import { ContextMenu as ContextMenuPrimitive } from "radix-ui";
import { cn } from "@/lib/utils";

/** Surface styles shared by Content and SubContent. */
const menuSurface = [
  "z-(--z-dropdown) min-w-32 overflow-x-hidden overflow-y-auto p-1",
  "max-h-(--radix-context-menu-content-available-height)",
  "origin-(--radix-context-menu-content-transform-origin)",
  "rounded-md border bg-popover text-popover-foreground shadow-2 outline-none",
  "motion-safe:transition-opacity motion-safe:duration-(--duration-fast) motion-safe:ease-standard",
  "data-[state=open]:opacity-100 data-[state=closed]:opacity-0",
  "motion-safe:data-[state=open]:animate-scale-in",
];

/** Row styles shared by Item, CheckboxItem, RadioItem and SubTrigger. */
const menuItem = [
  "relative flex cursor-default select-none items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-none",
  "transition-[background-color,color] duration-(--duration-fast) ease-standard",
  "focus:bg-accent focus:text-accent-foreground",
  "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*=size-])]:size-4",
];

function ContextMenu(props: React.ComponentProps<typeof ContextMenuPrimitive.Root>) {
  return <ContextMenuPrimitive.Root {...props} />;
}

function ContextMenuTrigger({
  className,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Trigger>) {
  return (
    <ContextMenuPrimitive.Trigger
      data-slot="context-menu-trigger"
      className={cn(className)}
      {...props}
    />
  );
}

function ContextMenuPortal(props: React.ComponentProps<typeof ContextMenuPrimitive.Portal>) {
  return <ContextMenuPrimitive.Portal {...props} />;
}

function ContextMenuGroup({
  className,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Group>) {
  return (
    <ContextMenuPrimitive.Group
      data-slot="context-menu-group"
      className={cn(className)}
      {...props}
    />
  );
}

function ContextMenuContent({
  className,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Content>) {
  return (
    <ContextMenuPrimitive.Portal>
      <ContextMenuPrimitive.Content
        data-slot="context-menu-content"
        className={cn(menuSurface, className)}
        {...props}
      />
    </ContextMenuPrimitive.Portal>
  );
}

export interface ContextMenuItemProps extends React.ComponentProps<
  typeof ContextMenuPrimitive.Item
> {
  /** `destructive` tints the row for irreversible actions. */
  variant?: "default" | "destructive";
  /** Pad the inline start so the label lines up with rows that carry an indicator. */
  inset?: boolean;
}

function ContextMenuItem({
  className,
  variant = "default",
  inset = false,
  ...props
}: ContextMenuItemProps) {
  return (
    <ContextMenuPrimitive.Item
      data-slot="context-menu-item"
      data-variant={variant}
      data-inset={inset || undefined}
      className={cn(
        menuItem,
        variant === "destructive" &&
          "text-destructive focus:bg-destructive/10 focus:text-destructive",
        inset && "ps-8",
        className,
      )}
      {...props}
    />
  );
}

function ContextMenuCheckboxItem({
  className,
  children,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.CheckboxItem>) {
  return (
    <ContextMenuPrimitive.CheckboxItem
      data-slot="context-menu-checkbox-item"
      className={cn(menuItem, "ps-8", className)}
      {...props}
    >
      <span className="pointer-events-none absolute start-2 flex size-4 items-center justify-center">
        <ContextMenuPrimitive.ItemIndicator>
          <Check className="size-4" />
        </ContextMenuPrimitive.ItemIndicator>
      </span>
      {children}
    </ContextMenuPrimitive.CheckboxItem>
  );
}

function ContextMenuRadioGroup({
  className,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.RadioGroup>) {
  return (
    <ContextMenuPrimitive.RadioGroup
      data-slot="context-menu-radio-group"
      className={cn(className)}
      {...props}
    />
  );
}

function ContextMenuRadioItem({
  className,
  children,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.RadioItem>) {
  return (
    <ContextMenuPrimitive.RadioItem
      data-slot="context-menu-radio-item"
      className={cn(menuItem, "ps-8", className)}
      {...props}
    >
      <span className="pointer-events-none absolute start-2 flex size-4 items-center justify-center">
        <ContextMenuPrimitive.ItemIndicator>
          <Circle className="size-2" fill="currentColor" />
        </ContextMenuPrimitive.ItemIndicator>
      </span>
      {children}
    </ContextMenuPrimitive.RadioItem>
  );
}

export interface ContextMenuLabelProps extends React.ComponentProps<
  typeof ContextMenuPrimitive.Label
> {
  /** Pad the inline start so the label lines up with rows that carry an indicator. */
  inset?: boolean;
}

function ContextMenuLabel({ className, inset = false, ...props }: ContextMenuLabelProps) {
  return (
    <ContextMenuPrimitive.Label
      data-slot="context-menu-label"
      data-inset={inset || undefined}
      className={cn(
        "px-2 py-1.5 text-xs font-semibold text-muted-foreground",
        inset && "ps-8",
        className,
      )}
      {...props}
    />
  );
}

function ContextMenuSeparator({
  className,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.Separator>) {
  return (
    <ContextMenuPrimitive.Separator
      data-slot="context-menu-separator"
      className={cn("-mx-1 my-1 h-px bg-border", className)}
      {...props}
    />
  );
}

function ContextMenuShortcut({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="context-menu-shortcut"
      // `ms-auto` parks the hint at the inline end in both directions.
      className={cn("ms-auto text-xs tracking-widest text-muted-foreground", className)}
      {...props}
    />
  );
}

function ContextMenuSub(props: React.ComponentProps<typeof ContextMenuPrimitive.Sub>) {
  return <ContextMenuPrimitive.Sub {...props} />;
}

export interface ContextMenuSubTriggerProps extends React.ComponentProps<
  typeof ContextMenuPrimitive.SubTrigger
> {
  /** Pad the inline start so the label lines up with rows that carry an indicator. */
  inset?: boolean;
}

function ContextMenuSubTrigger({
  className,
  inset = false,
  children,
  ...props
}: ContextMenuSubTriggerProps) {
  return (
    <ContextMenuPrimitive.SubTrigger
      data-slot="context-menu-sub-trigger"
      data-inset={inset || undefined}
      className={cn(
        menuItem,
        "data-[state=open]:bg-accent data-[state=open]:text-accent-foreground",
        inset && "ps-8",
        className,
      )}
      {...props}
    >
      {children}
      {/* The chevron points into the submenu, which opens towards the left in RTL. */}
      <ChevronRight className="ms-auto size-4 rtl:-scale-x-100" />
    </ContextMenuPrimitive.SubTrigger>
  );
}

function ContextMenuSubContent({
  className,
  ...props
}: React.ComponentProps<typeof ContextMenuPrimitive.SubContent>) {
  return (
    <ContextMenuPrimitive.SubContent
      data-slot="context-menu-sub-content"
      className={cn(menuSurface, "shadow-3", className)}
      {...props}
    />
  );
}

export {
  ContextMenu,
  ContextMenuTrigger,
  ContextMenuPortal,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuCheckboxItem,
  ContextMenuRadioGroup,
  ContextMenuRadioItem,
  ContextMenuLabel,
  ContextMenuSeparator,
  ContextMenuShortcut,
  ContextMenuGroup,
  ContextMenuSub,
  ContextMenuSubTrigger,
  ContextMenuSubContent,
};

