}

export interface PaginationLinkProps extends React.ComponentProps<"a"> {
  /** Marks the page the reader is on; also sets `aria-current="page"`. */
  isActive?: boolean;
  size?: ButtonProps["size"];
}

function PaginationLink({
  className,
  isActive = false,
  size = "icon",
  ...props
}: PaginationLinkProps) {
  return (
