}

export interface SidebarMenuButtonProps extends React.ComponentProps<"button"> {
  /** Marks the row for the section currently on screen. */
  isActive?: boolean;
  /** Glyph pinned at the inline start; it is all that survives in collapsed mode. */
  icon?: React.ReactNode;
  /**
   * Text shown in the collapsed-mode tooltip. Defaults to `children` when that
   * is a plain string.
   */
  tooltip?: React.ReactNode;
  /**
   * Render the child element instead of a `<button>`, for router links. Slot
   * takes exactly one child, so with `asChild` the caller supplies the icon and
   * the label itself and the `icon` prop is ignored.
   */
  asChild?: boolean;
}

function SidebarMenuButton({
  className,
  isActive = false,
  icon,
  tooltip,
  asChild = false,
  children,
  ...props
}: SidebarMenuButtonProps) {
  const { state, isMobile, direction } = useSidebar();

  const classes = cn(
    "flex h-(--control-h-md) w-full items-center gap-2 overflow-hidden rounded-control px-2 text-start text-sm",
    "text-sidebar-foreground outline-none select-none",
    "transition-[background-color,color,box-shadow] duration-(--duration-fast) ease-standard",
    "hover:bg-sidebar-accent hover:text-sidebar-accent-foreground",
    "focus-visible:ring-2 focus-visible:ring-sidebar-ring",
    "disabled:pointer-events-none disabled:opacity-50 aria-disabled:pointer-events-none aria-disabled:opacity-50",
    "data-[active=true]:bg-sidebar-primary data-[active=true]:font-medium data-[active=true]:text-sidebar-primary-foreground",
    "[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
    "group-data-[state=collapsed]/sidebar:justify-center group-data-[state=collapsed]/sidebar:px-0",
    className,
  );

  const shared = {
    "data-slot": "sidebar-menu-button",
    "data-active": isActive || undefined,
    "aria-current": isActive ? ("page" as const) : undefined,
    className: classes,
    ...props,
  };

  // Slot must receive exactly one child, so the icon and the label wrapper can
  // never be injected alongside a caller-supplied element.
  const button = asChild ? (
    <Slot.Root {...shared}>{children}</Slot.Root>
  ) : (
    <button type="button" {...shared}>
      {icon ? (
        <span data-slot="sidebar-menu-button-icon" aria-hidden="true" className="flex shrink-0">
          {icon}
        </span>
      ) : null}
      <span
        data-slot="sidebar-menu-button-label"
        className="min-w-0 flex-1 truncate group-data-[state=collapsed]/sidebar:hidden"
      >
        {children}
      </span>
    </button>
  );

  const hint = tooltip ?? (typeof children === "string" ? children : undefined);
  if (!hint || isMobile || state === "expanded") {
    return button;
  }

  return (
    <Tooltip>
      <TooltipTrigger asChild>{button}</TooltipTrigger>
      <TooltipContent side={direction === "rtl" ? "left" : "right"} sideOffset={8}>
        {hint}
      </TooltipContent>
    </Tooltip>
  );
}

export interface SidebarTriggerProps extends React.ComponentProps<typeof Button> {
  /** Accessible name of the icon-only button. */
  label?: string;
}

function SidebarTrigger({ className, label: labelProp, onClick, ...props }: SidebarTriggerProps) {
  const t = useT();
  const label = labelProp ?? t("sidebar.toggle");

  const { toggleSidebar, state, openMobile, isMobile } = useSidebar();

  return (
    <Button
      data-slot="sidebar-trigger"
      variant="ghost"
      size="icon-sm"
      aria-label={label}
      aria-expanded={isMobile ? openMobile : state === "expanded"}
      className={cn("shrink-0", className)}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented) toggleSidebar();
      }}
      {...props}
    >
      {/* The panel glyph points at the start edge, which flips in RTL. */}
      <PanelLeft aria-hidden="true" className="rtl:-scale-x-100" />
    </Button>
  );
}

function SidebarInset({ className, ...props }: React.ComponentProps<"main">) {
  return (
    <main
      data-slot="sidebar-inset"
      className={cn("flex min-h-svh min-w-0 flex-1 flex-col bg-background", className)}
      {...props}
    />
  );
}

export {
  SidebarProvider,
  Sidebar,
  SidebarHeader,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuItem,
  SidebarMenuButton,
  SidebarTrigger,
  SidebarInset,
  useSidebar,
};

"use client";

/** Recharts wrappers that map series keys to labels and token colours, plus tooltip and legend content styled with the design system's surfaces. */
import * as React from "react";
import { Legend, ResponsiveContainer, Tooltip } from "recharts";
import { cn } from "@/lib/utils";

/** Fallback ramp: series with no explicit colour cycle through the chart tokens. */
const CHART_PALETTE = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
] as const;

export interface ChartSeriesConfig {
  /** Human name of the series, used in the tooltip and the legend. */
  label?: React.ReactNode;
  /** Glyph rendered before the label instead of the colour swatch. */
  icon?: React.ComponentType<{ className?: string }>;
  /**
   * Any CSS colour. Defaults to `var(--chart-1..5)` by position, so a chart is
   * on-palette without naming a single colour.
   */
  color?: string;
}

/** Maps every `dataKey` in a chart to its label and colour. */
export type ChartConfig = Record<string, ChartSeriesConfig>;

interface ChartContextValue {
  config: ChartConfig;
}

const ChartContext = React.createContext<ChartContextValue | null>(null);

/** Read the surrounding chart's config. Throws outside a `ChartContainer`. */
function useChart(): ChartContextValue {
  const context = React.useContext(ChartContext);
  if (!context) {
    throw new Error("useChart must be used inside a <ChartContainer>.");
  }
  return context;
}

/** Resolves the colour a series should use, falling back to the token ramp. */
function seriesColor(config: ChartConfig, key: string): string {
  const index = Object.keys(config).indexOf(key);
  const fallback =
    CHART_PALETTE[(index < 0 ? 0 : index) % CHART_PALETTE.length] ?? CHART_PALETTE[0];
  return config[key]?.color ?? fallback;
}

export interface ChartContainerProps extends Omit<React.ComponentProps<"div">, "children"> {
  /** Series keys mapped to their label and colour. */
  config: ChartConfig;
  /** The recharts chart element. */
  children: React.ComponentProps<typeof ResponsiveContainer>["children"];
  /** Accessible name for the figure. */
  label?: string;
}

function ChartContainer({
  className,
  config,
  children,
  label,
  style,
  ...props
}: ChartContainerProps) {
  // Every series key becomes a `--color-<key>` custom property on the wrapper,
  // so a chart child can write fill="var(--color-revenue)" and stay on palette
  // through brand and colour-mode switches.
  const variables = React.useMemo(() => {
    const entries: Record<string, string> = {};
    for (const key of Object.keys(config)) {
      entries[`--color-${key}`] = seriesColor(config, key);
    }
    return entries as React.CSSProperties;
  }, [config]);

  const value = React.useMemo(() => ({ config }), [config]);

  return (
    <ChartContext.Provider value={value}>
      <div
        data-slot="chart"
        // A figure role without a name says nothing useful, so it only appears
        // once the caller has supplied one.
        role={label ? "img" : undefined}
        aria-label={label}
        className={cn(
          "flex aspect-video w-full justify-center text-xs",
          "[&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground",
          "[&_.recharts-cartesian-grid_line]:stroke-border/60",
          "[&_.recharts-curve.recharts-tooltip-cursor]:stroke-border",
          "[&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted/50",
          "[&_.recharts-reference-line_line]:stroke-border",
          /* design-eg-lint-disable-next-line raw-color */
          "[&_.recharts-sector[stroke='#fff']]:stroke-transparent", // matches recharts' own default stroke value
          "[&_.recharts-surface]:outline-none",
          className,
        )}
        style={{ ...variables, ...style }}
        {...props}
      >
        <ResponsiveContainer>{children}</ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  );
}

/** The recharts `Tooltip`, re-exported so charts import everything from one place. */
const ChartTooltip = Tooltip;

/** The recharts `Legend`, re-exported so charts import everything from one place. */
const ChartLegend = Legend;

/**
 * One entry of what recharts hands to a custom tooltip or legend. It is typed
 * structurally rather than with the library's generics, because the content
 * props are supplied by recharts at runtime through `cloneElement`.
 */
export interface ChartPayloadItem {
  value?: number | string;
  name?: number | string;
  dataKey?: string | number;
  color?: string;
  fill?: string;
  payload?: Record<string, unknown>;
  [key: string]: unknown;
}

export interface ChartTooltipContentProps extends Omit<React.ComponentProps<"div">, "content"> {
  /** Set by recharts while the cursor is over the chart. */
  active?: boolean;
  /** Set by recharts: one entry per series at the hovered position. */
  payload?: ReadonlyArray<ChartPayloadItem>;
  /** Set by recharts: the category value under the cursor. */
  label?: React.ReactNode;
  /** Hide the heading row. */
  hideLabel?: boolean;
  /** Hide the colour swatches. */
  hideIndicator?: boolean;
  /** Shape of the swatch. */
  indicator?: "dot" | "line" | "dashed";
  /** Rewrite the heading, e.g. to format a date. */
  labelFormatter?: (
    label: React.ReactNode,
    payload: ReadonlyArray<ChartPayloadItem>,
  ) => React.ReactNode;
  /** Rewrite a single value, e.g. to add a currency symbol. */
  valueFormatter?: (value: number | string | undefined, item: ChartPayloadItem) => React.ReactNode;
}

function ChartTooltipContent({
  className,
  active,
  payload,
  label,
  hideLabel = false,
  hideIndicator = false,
  indicator = "dot",
  labelFormatter,
  valueFormatter,
  ...props
}: ChartTooltipContentProps) {
  const { config } = useChart();

  if (!active || !payload || payload.length === 0) return null;

  const heading = labelFormatter ? labelFormatter(label, payload) : label;

  return (
    <div
      data-slot="chart-tooltip"
      className={cn(
        "min-w-32 rounded-md border border-border bg-popover px-2.5 py-2 text-xs text-popover-foreground shadow-2",
        className,
      )}
      {...props}
    >
      {hideLabel || heading === undefined || heading === null || heading === "" ? null : (
        <p data-slot="chart-tooltip-label" className="mb-1.5 font-medium">
          {heading}
        </p>
      )}

      <ul className="flex flex-col gap-1">
        {payload.map((item, index) => {
          const key = String(item.dataKey ?? item.name ?? index);
          const series = config[key];
          const color = item.color ?? item.fill ?? seriesColor(config, key);
          const Icon = series?.icon;

          return (
            <li key={key} data-slot="chart-tooltip-item" className="flex items-center gap-2">
              {hideIndicator ? null : Icon ? (
                <Icon className="size-3 shrink-0 text-muted-foreground" />
              ) : (
                <span
                  aria-hidden="true"
                  className={cn(
                    "shrink-0",
                    indicator === "dot" && "size-2.5 rounded-full",
                    indicator === "line" && "h-0.5 w-3 rounded-full",
                    indicator === "dashed" && "h-0 w-3 border-t-2 border-dashed",
                  )}
                  style={
                    indicator === "dashed" ? { borderColor: color } : { backgroundColor: color }
                  }
                />
              )}
              <span className="text-muted-foreground">{series?.label ?? item.name ?? key}</span>
              <span className="ms-auto font-medium tabular-nums text-foreground">
                {valueFormatter ? valueFormatter(item.value, item) : item.value}
              </span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

export interface ChartLegendContentProps extends Omit<React.ComponentProps<"div">, "content"> {
  /** Set by recharts: one entry per series. */
  payload?: ReadonlyArray<ChartPayloadItem>;
  /** Where recharts placed the legend, used to pick the right margin. */
  verticalAlign?: "top" | "middle" | "bottom";
  /** Hide the colour swatches. */
  hideIcon?: boolean;
}

function ChartLegendContent({
  className,
  payload,
  verticalAlign = "bottom",
  hideIcon = false,
  ...props
}: ChartLegendContentProps) {
  const { config } = useChart();

  if (!payload || payload.length === 0) return null;

  return (
    <div
      data-slot="chart-legend"
      className={cn(
        "flex flex-wrap items-center justify-center gap-4",
        verticalAlign === "top" ? "pb-3" : "pt-3",
        className,
      )}
      {...props}
    >
      {payload.map((item, index) => {
        const key = String(item.dataKey ?? item.value ?? index);
        const series = config[key];
        const color = item.color ?? seriesColor(config, key);
        const Icon = series?.icon;

        return (
          <div
            key={key}
            data-slot="chart-legend-item"
            className="flex items-center gap-1.5 text-xs text-muted-foreground"
          >
            {hideIcon ? null : Icon ? (
              <Icon className="size-3 shrink-0" />
            ) : (
              <span
                aria-hidden="true"
                className="size-2.5 shrink-0 rounded-xs"
                style={{ backgroundColor: color }}
              />
            )}
            {series?.label ?? item.value ?? key}
          </div>
        );
      })}
    </div>
  );
}

export {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  ChartLegend,
  ChartLegendContent,
  useChart,
};

"use client";

/** Code surface with a file-name bar, optional line numbers and a copy button that confirms through a toast. Deliberately unhighlighted: no tokenizer dependency, no hydration mismatch. */
import * as React from "react";
import { cn } from "@/lib/utils";
import { useT } from "@/lib/i18n";
import { CopyButton } from "@/components/ui/copy-button";
import { notify } from "@/components/ui/sonner";

export interface CodeBlockProps extends Omit<React.ComponentProps<"div">, "children"> {
  /** The text shown, and the exact text the copy button writes. */
  code: string;
  /** Gutter label: a file name, or a language such as `bash`. */
  label?: string;
  /** Accessible name for the copy button. */
  copyLabel?: string;
  /** Toast on a successful copy: `false` stays silent, a string replaces the message. */
  toast?: boolean | string;
  /** Number the lines. The numbers are decoration and never reach the clipboard. */
  lineNumbers?: boolean;
  /** Height at which the block starts scrolling, as a CSS length. */
  maxHeight?: string;
  /** Drop the header bar and float the copy button over the code instead. */
  hideHeader?: boolean;
}

function CodeBlock({
  className,
  code,
  label = "tsx",
  copyLabel: copyLabelProp,
  toast = true,
  lineNumbers = false,
  maxHeight = "32rem",
  hideHeader = false,
  ...props
}: CodeBlockProps) {
  const t = useT();
  const copyLabel = copyLabelProp ?? t("codeBlock.copy");
  const lines = React.useMemo(() => code.replace(/\n$/, "").split("\n"), [code]);

  const handleCopy = React.useCallback(() => {
    if (toast === false) return;
    // `undefined` lets notify fall back to its own translated default.
    notify.copied(typeof toast === "string" ? toast : undefined);
  }, [toast]);

  return (
    <div
      data-slot="code-block"
      className={cn("group relative overflow-hidden rounded-card border bg-surface-1", className)}
      {...props}
    >
      {hideHeader ? (
        <div className="absolute top-2 end-2 z-(--z-raised)">
          <CopyButton
            value={code}
            copyLabel={copyLabel}
            variant="outline"
            className="bg-surface-2 opacity-0 focus-visible:opacity-100 group-hover:opacity-100"
            onCopy={handleCopy}
          />
        </div>
      ) : (
        <div className="flex items-center justify-between gap-2 border-b bg-surface-2 ps-4 pe-2 py-1.5">
          <span className="truncate font-mono text-xs text-muted-foreground">{label}</span>
          <CopyButton value={code} copyLabel={copyLabel} onCopy={handleCopy} />
        </div>
      )}

      <pre
        data-slot="code-block-pre"
        dir="ltr"
        className="overflow-auto p-4 text-start font-mono text-xs leading-relaxed"
        style={{ maxHeight }}
      >
        <code>
          {lineNumbers
            ? lines.map((line, index) => (
                <span key={index} className="grid grid-cols-[2.5rem_1fr]">
                  <span aria-hidden="true" className="select-none text-muted-foreground/60">
                    {index + 1}
                  </span>
                  <span>{line}</span>
                </span>
              ))
            : code}
        </code>
      </pre>
    </div>
  );
}

export { CodeBlock };

"use client";

/** Confirmation prompt over AlertDialog that awaits an async handler, keeps itself open while the action runs, and shows a spinner on the confirm button. */
import * as React from "react";
import { LoaderCircle } from "lucide-react";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { cn } from "@/lib/utils";
import { useT } from "@/lib/i18n";

export interface ConfirmDialogProps extends Omit<
  React.ComponentProps<typeof AlertDialogContent>,
  "title" | "onError"
> {
  /** Question posed to the user. */
  title: React.ReactNode;
  /** What will happen if they confirm, including anything irreversible. */
  description?: React.ReactNode;
  /** Text of the confirm button. */
  confirmLabel?: string;
  /** Text of the cancel button. */
  cancelLabel?: string;
  /** Tint the confirm button as destructive for irreversible actions. */
  destructive?: boolean;
  /**
   * Runs when the user confirms. While the returned promise is pending the
   * dialog stays open and both buttons are blocked; the dialog closes once it
   * resolves, and stays open if it rejects.
   */
  onConfirm: () => void | Promise<void>;
  /** Called when `onConfirm` rejects, so the caller can surface the failure. */
  onError?: (error: unknown) => void;
  /** Element that opens the dialog. Omit it when driving `open` yourself. */
  trigger?: React.ReactNode;
  /** Controlled open state. */
  open?: boolean;
  /** Notified whenever the open state changes, controlled or not. */
  onOpenChange?: (open: boolean) => void;
  /** Initial open state when the component owns it. */
  defaultOpen?: boolean;
}

function ConfirmDialog({
  className,
  title,
  description,
  confirmLabel: confirmLabelProp,
  cancelLabel: cancelLabelProp,
  destructive = false,
  onConfirm,
  onError,
  trigger,
  open,
  onOpenChange,
  defaultOpen = false,
  children,
  ...props
}: ConfirmDialogProps) {
  const t = useT();
  const confirmLabel = confirmLabelProp ?? t("confirmDialog.confirm");
  const cancelLabel = cancelLabelProp ?? t("confirmDialog.cancel");

  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen);
  const [pending, setPending] = React.useState(false);

  const isOpen = open ?? uncontrolledOpen;

  const setOpen = React.useCallback(
    (next: boolean) => {
      if (open === undefined) setUncontrolledOpen(next);
      onOpenChange?.(next);
    },
    [onOpenChange, open],
  );

  const handleConfirm = async (event: React.MouseEvent<HTMLButtonElement>) => {
    // Radix closes on click by default; the dialog has to survive long enough
    // to show the pending state and to stay open if the action fails.
    event.preventDefault();
    if (pending) return;

    try {
      setPending(true);
      await onConfirm();
      setOpen(false);
    } catch (error) {
      onError?.(error);
    } finally {
      setPending(false);
    }
  };

  return (
    <AlertDialog
      open={isOpen}
      onOpenChange={(next) => {
        // Escape and the cancel button must not dismiss a running action.
        if (pending && !next) return;
        setOpen(next);
      }}
    >
      {trigger ? <AlertDialogTrigger asChild>{trigger}</AlertDialogTrigger> : null}

      <AlertDialogContent data-slot="confirm-dialog" className={cn(className)} {...props}>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          {description ? <AlertDialogDescription>{description}</AlertDialogDescription> : null}
        </AlertDialogHeader>

        {children}

        <AlertDialogFooter>
          <AlertDialogCancel disabled={pending}>{cancelLabel}</AlertDialogCancel>
          <AlertDialogAction
            data-slot="confirm-dialog-confirm"
            data-loading={pending || undefined}
            aria-busy={pending || undefined}
            disabled={pending}
            onClick={handleConfirm}
            className={cn(
              destructive &&
                "bg-destructive text-destructive-foreground hover:bg-destructive/90 active:bg-destructive/80",
            )}
          >
            {pending ? <LoaderCircle aria-hidden="true" className="size-4 animate-spin" /> : null}
            {confirmLabel}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

export { ConfirmDialog };

