import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { useI18n } from "@/lib/i18n";

export interface ProductCardImage {
  src?: string;
  /**
   * Empty by default: the linked title right below already names the product,
   * so repeating it in the image would make a screen reader say it twice.
   */
  alt?: string;
  /** Drawn on the fallback surface when there is no `src`, or when it fails to load. */
  fallback?: React.ReactNode;
}

export type ProductCardTitleTag = "h2" | "h3" | "h4";

export interface ProductCardProps extends Omit<React.ComponentProps<"div">, "title"> {
  /** Product name. Rendered as the card's link. */
  title: string;
  /** Destination of the title link, which also stretches over the whole card. */
  href?: string;
  image?: ProductCardImage;
  /** Short label over the image, e.g. "New" or "-20%". */
  badge?: React.ReactNode;
  badgeVariant?: BadgeProps["variant"];
  /** Small line above the title, such as a category or a maker. */
  eyebrow?: React.ReactNode;
  /** Average rating. Omit it to hide the stars. */
  rating?: number;
  /** Highest possible rating. */
  ratingMax?: number;
  reviewCount?: number;
  /** Selling price in major units, e.g. `24.5`. Formatted in the active locale. */
  price: number;
  /** Price before the discount. Shown struck through only when it is higher than `price`. */
  compareAtPrice?: number;
  /** ISO 4217 code. */
  currency?: string;
  /** Heading level of the title, so the card fits the outline of the page around it. */
  titleAs?: ProductCardTitleTag;
  onAddToCart?: () => void;
  /** Visible text of the add-to-cart button. */
  addToCartLabel?: string;
  /** Hides the add-to-cart button, e.g. for an out-of-stock listing. */
  hideAddToCart?: boolean;
  /** Controlled wishlist state. */
  wishlisted?: boolean;
  defaultWishlisted?: boolean;
  onWishlistChange?: (wishlisted: boolean) => void;
  /** Accessible name of the wishlist toggle. Its pressed state is announced separately. */
  wishlistLabel?: string;
  /** Hides the wishlist toggle. */
  hideWishlist?: boolean;
}

function ProductCardStars({ value, max }: { value: number; max: number }) {
  const percent = max > 0 ? Math.min(100, Math.max(0, (value / max) * 100)) : 0;
  const row = (filled: boolean) =>
    Array.from({ length: max }, (_, index) => (
      <Star
        key={index}
        aria-hidden="true"
        className={cn("size-4 shrink-0", filled && "fill-current")}
      />
    ));

  // Two identical rows of stars: an empty one, and a filled one clipped to the
  // rating from the inline start, so half stars need no second glyph and the
  // fill grows the right way in RTL too.
  return (
    <span
      data-slot="product-card-stars"
      aria-hidden="true"
      className="relative inline-flex text-muted-foreground/40"
    >
      {row(false)}
      <span
        className="absolute inset-y-0 start-0 flex overflow-hidden text-warning"
        style={{ width: `${percent}%` }}
      >
        {row(true)}
      </span>
    </span>
  );
}

function ProductCard({
  className,
  title,
  href = "#",
  image,
  badge,
  badgeVariant = "default",
  eyebrow,
  rating,
  ratingMax = 5,
  reviewCount,
  price,
  compareAtPrice,
  currency = "USD",
  titleAs: Title = "h3",
  onAddToCart,
  addToCartLabel: addToCartLabelProp,
  hideAddToCart = false,
  wishlisted,
  defaultWishlisted,
  onWishlistChange,
  wishlistLabel: wishlistLabelProp,
  hideWishlist = false,
  ...props
}: ProductCardProps) {
  const { t, locale } = useI18n();
  const titleId = React.useId();

  const money = React.useMemo(
    () => new Intl.NumberFormat(locale, { style: "currency", currency }),
    [locale, currency],
  );

  // A custom label is used verbatim, with the product name as its description;
  // the built-in one names the product itself, starting with the visible words
  // so voice control users can still say what they see.
  const addToCartLabel = addToCartLabelProp ?? t("productCard.addToCart");
  const addToCartName = addToCartLabelProp ? undefined : t("productCard.addToCartNamed", { title });
  const wishlistLabel = wishlistLabelProp ?? t("productCard.wishlist", { title });

  const ratingLabel =
    rating === undefined
      ? undefined
      : reviewCount === undefined
        ? t("productCard.ratingOnly", { rating, max: ratingMax })
        : t("productCard.rating", { rating, max: ratingMax, count: reviewCount });

  const onSale = compareAtPrice !== undefined && compareAtPrice > price;

  // Keyed on the source, so a new `src` gets a fresh attempt at loading.
  const [failedSrc, setFailedSrc] = React.useState<string>();
  const showImage = Boolean(image?.src) && failedSrc !== image?.src;
  const alt = image?.alt ?? "";

  return (
    <div
      data-slot="product-card"
      className={cn(
        "group/product-card relative isolate flex flex-col overflow-hidden rounded-card border bg-card text-card-foreground shadow-1",
        "transition-[border-color,box-shadow] duration-(--duration-normal) ease-standard",
        "hover:border-primary/40 hover:shadow-2",
        "has-[[data-slot=product-card-link]:focus-visible]:ring-2 has-[[data-slot=product-card-link]:focus-visible]:ring-ring",
        className,
      )}
      {...props}
    >
      <div
        data-slot="product-card-media"
        className="relative aspect-square overflow-hidden bg-surface-2"
      >
        {showImage ? (
          <img
            data-slot="product-card-image"
            src={image?.src}
            alt={alt}
            loading="lazy"
            decoding="async"
            onError={() => setFailedSrc(image?.src)}
            className={cn(
              "size-full object-cover",
              "motion-safe:transition-transform motion-safe:duration-(--duration-slower) motion-safe:ease-standard",
              "motion-safe:group-hover/product-card:scale-105",
            )}
          />
        ) : (
          <div
            data-slot="product-card-fallback"
            role={alt ? "img" : undefined}
            aria-label={alt || undefined}
            aria-hidden={alt ? undefined : true}
            className={cn(
              "flex size-full items-center justify-center bg-surface-2 text-muted-foreground",
              "[background-image:radial-gradient(90%_70%_at_50%_20%,color-mix(in_oklab,var(--primary)_10%,transparent),transparent_70%)]",
            )}
          >
            {image?.fallback ?? <ImageIcon aria-hidden="true" className="size-10 opacity-40" />}
          </div>
        )}

        {badge ? (
          <Badge
            data-slot="product-card-badge"
            variant={badgeVariant}
            className="absolute top-3 start-3 shadow-1"
          >
            {badge}
          </Badge>
        ) : null}

        {hideWishlist ? null : (
          <TogglePrimitive.Root
            data-slot="product-card-wishlist"
            pressed={wishlisted}
            defaultPressed={defaultWishlisted}
            onPressedChange={onWishlistChange}
            aria-label={wishlistLabel}
            className={cn(
              "absolute top-2 end-2 z-(--z-raised) inline-flex size-(--control-h-sm) items-center justify-center rounded-full",
              "bg-background/85 text-foreground shadow-1 backdrop-blur-sm",
              "transition-[color,background-color,transform] duration-(--duration-fast) ease-standard",
              "hover:bg-background hover:text-primary",
              "outline-none focus-visible:ring-2 focus-visible:ring-ring",
              "data-[state=on]:text-primary [&[data-state=on]_svg]:fill-current",
              "motion-safe:active:scale-90",
              "[&_svg]:size-4",
            )}
          >
            <Heart aria-hidden="true" />
          </TogglePrimitive.Root>
        )}
      </div>

      <div data-slot="product-card-body" className="flex flex-1 flex-col gap-2 p-4">
        {eyebrow ? (
          <p
            data-slot="product-card-eyebrow"
            className="text-eyebrow font-semibold uppercase text-muted-foreground"
          >
            {eyebrow}
          </p>
        ) : null}

        <Title data-slot="product-card-title" className="text-body font-semibold leading-snug">
          <a
            id={titleId}
            data-slot="product-card-link"
            href={href}
            className={cn(
              "line-clamp-2 outline-none",
              "transition-colors duration-(--duration-fast) ease-standard hover:text-primary",
              "focus-visible:underline focus-visible:underline-offset-4",
              // One focus stop for the whole card: the link's hit area covers
              // it, and only the two buttons are raised above.
              "after:absolute after:inset-0 after:content-['']",
            )}
          >
            {title}
          </a>
        </Title>

        {ratingLabel ? (
          <div
            data-slot="product-card-rating"
            role="img"
            aria-label={ratingLabel}
            className="flex items-center gap-1.5"
          >
            <ProductCardStars value={rating ?? 0} max={ratingMax} />
            {reviewCount !== undefined ? (
              <span aria-hidden="true" className="text-caption text-muted-foreground tabular-nums">
                ({new Intl.NumberFormat(locale).format(reviewCount)})
              </span>
            ) : null}
          </div>
        ) : null}

        <p data-slot="product-card-price" className="flex flex-wrap items-baseline gap-x-2">
          {onSale ? <span className="sr-only">{t("productCard.currentPrice")} </span> : null}
          <span
            data-slot="product-card-current-price"
            className={cn("text-body font-semibold tabular-nums", onSale && "text-primary")}
          >
            {money.format(price)}
          </span>
          {onSale ? (
            <s
              data-slot="product-card-compare-price"
              className="text-sm text-muted-foreground tabular-nums"
            >
              <span className="sr-only">{t("productCard.originalPrice")} </span>
              {money.format(compareAtPrice)}
            </s>
          ) : null}
        </p>

        {hideAddToCart ? null : (
          <div data-slot="product-card-actions" className="mt-auto pt-2">
            <Button
              data-slot="product-card-add"
              type="button"
              size="sm"
              aria-label={addToCartName}
              aria-describedby={addToCartName ? undefined : titleId}
              onClick={onAddToCart}
              className="relative z-(--z-raised) w-full"
            >
              <ShoppingBag aria-hidden="true" />
              {addToCartLabel}
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}

export { ProductCard };

"use client";

/** Site footer with a brand blurb, column groups of links, a social and legal row, and a copyright line, each group its own navigation landmark. */
import * as React from "react";
import { cn } from "@/lib/utils";
import { useT } from "@/lib/i18n";
import { Separator } from "@/components/ui/separator";

export interface SiteFooterLink {
  label: string;
  href: string;
  /** Opens in a new tab and adds `rel="noopener noreferrer"`. */
  external?: boolean;
}

export interface SiteFooterGroup {
  /** Heading for the column; also names its navigation landmark. */
  title: string;
  links: SiteFooterLink[];
}

export interface SiteFooterSocialLink extends SiteFooterLink {
  /** Icon element; `label` becomes the accessible name. */
  icon?: React.ReactNode;
}

export interface SiteFooterProps extends React.ComponentProps<"footer"> {
  /** Wordmark or logo lockup. */
  brand?: React.ReactNode;
  /** A sentence or two under the brand. */
  blurb?: React.ReactNode;
  groups?: SiteFooterGroup[];
  social?: SiteFooterSocialLink[];
  legal?: SiteFooterLink[];
  /** Defaults to the current year with no owner name, so nothing is invented. */
  copyright?: React.ReactNode;
  /** Names the social navigation landmark. */
  socialLabel?: string;
  /** Names the legal navigation landmark. */
  legalLabel?: string;
}

const linkClass = cn(
  "text-sm text-muted-foreground underline-offset-4",
  "transition-colors duration-(--duration-fast) ease-standard",
  "hover:text-foreground hover:underline",
  "rounded-control outline-none focus-visible:ring-2 focus-visible:ring-ring",
);

function externalProps(link: SiteFooterLink) {
  return link.external ? { target: "_blank" as const, rel: "noopener noreferrer" } : {};
}

function SiteFooter({
  className,
  brand,
  blurb,
  groups = [],
  social = [],
  legal = [],
  copyright = `\u00A9 ${new Date().getFullYear()}`,
  socialLabel: socialLabelProp,
  legalLabel: legalLabelProp,
  children,
  ...props
}: SiteFooterProps) {
  const t = useT();
  const socialLabel = socialLabelProp ?? t("siteFooter.social");
  const legalLabel = legalLabelProp ?? t("siteFooter.legal");

  return (
    <footer
      data-slot="site-footer"
      className={cn("border-t bg-surface-1 text-foreground", className)}
      {...props}
    >
      <div className="mx-auto w-full max-w-(--container-content) px-(--gutter) py-(--section-y)">
        <div className={cn("grid gap-10", "md:grid-cols-[minmax(0,1fr)_minmax(0,2fr)] lg:gap-16")}>
          <div data-slot="site-footer-brand" className="flex flex-col gap-4">
            {brand ? <div className="font-display text-2xl tracking-wide">{brand}</div> : null}
            {blurb ? (
              <p className="max-w-prose text-sm text-pretty text-muted-foreground">{blurb}</p>
            ) : null}
            {children}
          </div>

          {groups.length > 0 ? (
            <div
              data-slot="site-footer-groups"
              className="grid gap-8 sm:grid-cols-2 lg:grid-cols-3"
            >
              {groups.map((group) => (
                <nav key={group.title} aria-label={group.title} className="flex flex-col gap-3">
                  <h2 className="text-eyebrow font-semibold uppercase text-foreground">
                    {group.title}
                  </h2>
                  <ul className="flex flex-col gap-2">
                    {group.links.map((link) => (
                      <li key={`${group.title}-${link.href}-${link.label}`}>
                        <a href={link.href} className={linkClass} {...externalProps(link)}>
                          {link.label}
                        </a>
                      </li>
                    ))}
                  </ul>
                </nav>
              ))}
            </div>
          ) : null}
        </div>

        <Separator className="my-8" />

        <div
          data-slot="site-footer-meta"
          className="flex flex-col-reverse items-start gap-4 sm:flex-row sm:items-center sm:justify-between"
        >
          <p data-slot="site-footer-copyright" className="text-sm text-muted-foreground">
            {copyright}
          </p>

          <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
            {legal.length > 0 ? (
              <nav aria-label={legalLabel}>
                <ul className="flex flex-wrap items-center gap-x-4 gap-y-2">
                  {legal.map((link) => (
                    <li key={`${link.href}-${link.label}`}>
                      <a href={link.href} className={linkClass} {...externalProps(link)}>
                        {link.label}
                      </a>
                    </li>
                  ))}
                </ul>
              </nav>
            ) : null}

            {social.length > 0 ? (
              <nav aria-label={socialLabel}>
                <ul className="flex items-center gap-1">
                  {social.map((link) => (
                    <li key={`${link.href}-${link.label}`}>
                      <a
                        href={link.href}
                        aria-label={link.label}
                        title={link.label}
                        className={cn(
                          "inline-flex size-9 items-center justify-center rounded-control",
                          "text-muted-foreground",
                          "transition-colors duration-(--duration-fast) ease-standard",
                          "hover:bg-accent hover:text-accent-foreground",
                          "outline-none focus-visible:ring-2 focus-visible:ring-ring",
                          "[&_svg]:size-4",
                        )}
                        {...externalProps(link)}
                      >
                        {link.icon ?? <span aria-hidden="true">{link.label.charAt(0)}</span>}
                      </a>
                    </li>
                  ))}
                </ul>
              </nav>
            ) : null}
          </div>
        </div>
      </div>
    </footer>
  );
}

export { SiteFooter };

"use client";

/** Sticky glass site header with a logo slot, inline navigation, action slot, and a sheet-based menu below the medium breakpoint. */
import * as React from "react";
import { Menu } from "lucide-react";
import { cn } from "@/lib/utils";
import { useT } from "@/lib/i18n";
import { Button } from "@/components/ui/button";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/components/ui/sheet";

export interface SiteNavbarLink {
  label: string;
  href: string;
  /** Marks the link as the current page for assistive tech. */
  active?: boolean;
  /** Opens in a new tab and adds `rel="noopener noreferrer"`. */
  external?: boolean;
}

export interface SiteNavbarProps extends React.ComponentProps<"header"> {
  /** Logo lockup. Defaults to a neutral brand mark linking home. */
  logo?: React.ReactNode;
  links?: SiteNavbarLink[];
  /** Buttons shown beside the navigation on wide screens. */
  actions?: React.ReactNode;
  /** Actions repeated at the bottom of the mobile sheet. Falls back to `actions`. */
  mobileActions?: React.ReactNode;
  /** Pin the header to the top of the viewport. */
  sticky?: boolean;
  /** Names the inline navigation landmark. */
  navLabel?: string;
  /** Accessible name for the menu button. */
  menuLabel?: string;
  /** Heading inside the mobile sheet. */
  menuTitle?: string;
  /** Description inside the mobile sheet; visually hidden but announced. */
  menuDescription?: string;
}

function DefaultLogo() {
  const t = useT();

  return (
    <a
      href="/"
      className={cn(
        "inline-flex items-center gap-2 font-display text-2xl tracking-wide",
        "rounded-control outline-none focus-visible:ring-2 focus-visible:ring-ring",
      )}
    >
      <span className="inline-block size-6 rounded-sm bg-primary" aria-hidden="true" />
      <span className="sr-only">{t("siteNavbar.home")}</span>
    </a>
  );
}

function externalProps(link: SiteNavbarLink) {
  return link.external ? { target: "_blank" as const, rel: "noopener noreferrer" } : {};
}

function SiteNavbar({
  className,
  logo = <DefaultLogo />,
  links = [],
  actions,
  mobileActions,
  sticky = true,
  navLabel: navLabelProp,
  menuLabel: menuLabelProp,
  menuTitle: menuTitleProp,
  menuDescription: menuDescriptionProp,
  children,
  ...props
}: SiteNavbarProps) {
  const t = useT();
  const navLabel = navLabelProp ?? t("siteNavbar.nav");
  const menuLabel = menuLabelProp ?? t("siteNavbar.openMenu");
  const menuTitle = menuTitleProp ?? t("siteNavbar.menuTitle");
  const menuDescription = menuDescriptionProp ?? t("siteNavbar.menuDescription");

  const [open, setOpen] = React.useState(false);

  return (
    <header
      data-slot="site-navbar"
      className={cn("top-0 z-(--z-sticky) w-full border-b glass", sticky && "sticky", className)}
      {...props}
    >
      <div className="mx-auto flex h-(--header-h) w-full max-w-(--container-content) items-center gap-4 px-(--gutter)">
        <div data-slot="site-navbar-logo" className="flex shrink-0 items-center">
          {logo}
        </div>

        {links.length > 0 ? (
          <nav
            data-slot="site-navbar-nav"
            aria-label={navLabel}
            className="ms-auto hidden items-center gap-1 md:flex"
          >
            {links.map((link) => (
              <Button
                key={`${link.href}-${link.label}`}
                variant="ghost"
                size="sm"
                asChild
                className={cn(link.active && "text-primary")}
              >
                <a
                  href={link.href}
                  aria-current={link.active ? "page" : undefined}
                  {...externalProps(link)}
                >
                  {link.label}
                </a>
              </Button>
            ))}
          </nav>
        ) : null}

        {children}

        <div
          data-slot="site-navbar-actions"
          className={cn("ms-auto flex items-center gap-2", links.length > 0 && "md:ms-4")}
        >
          {actions ? <div className="hidden items-center gap-2 md:flex">{actions}</div> : null}

          <Sheet open={open} onOpenChange={setOpen}>
            <SheetTrigger asChild>
              <Button
                variant="ghost"
                size="icon"
                aria-label={menuLabel}
                className="md:hidden"
                data-slot="site-navbar-menu-trigger"
              >
                <Menu />
              </Button>
            </SheetTrigger>
            <SheetContent side="end" className="w-[min(20rem,85vw)] gap-6">
              <SheetHeader>
                <SheetTitle>{menuTitle}</SheetTitle>
                <SheetDescription className="sr-only">{menuDescription}</SheetDescription>
              </SheetHeader>

              <nav
                data-slot="site-navbar-mobile-nav"
                aria-label={menuTitle}
                className="flex flex-col"
              >
                {links.map((link) => (
                  <a
                    key={`${link.href}-${link.label}`}
                    href={link.href}
                    aria-current={link.active ? "page" : undefined}
                    onClick={() => setOpen(false)}
                    className={cn(
                      "border-b py-3 text-body font-medium last:border-b-0",
                      "transition-colors duration-(--duration-fast) ease-standard",
                      "hover:text-primary",
                      "outline-none focus-visible:ring-2 focus-visible:ring-ring",
                      link.active && "text-primary",
                    )}
                    {...externalProps(link)}
                  >
                    {link.label}
                  </a>
                ))}
              </nav>

              {(mobileActions ?? actions) ? (
                <div className="mt-auto flex flex-col gap-2 [&>*]:w-full">
                  {mobileActions ?? actions}
                </div>
              ) : null}
            </SheetContent>
          </Sheet>
        </div>
      </div>
    </header>
  );
}

export { SiteNavbar };

"use client";

/** Bento grid of headline numbers in mixed tile sizes, with counters that animate the first time their tile scrolls into view. */
import * as React from "react";
import { cn } from "@/lib/utils";

/** `useLayoutEffect` warns during SSR, so fall back to the passive effect there. */
const useIsomorphicLayoutEffect =
  typeof window === "undefined" ? React.useEffect : React.useLayoutEffect;

/**
 * Tracks `prefers-reduced-motion`. It starts as `false` so the server and the
 * first client render agree; the effect corrects it before anything moves.
 */
function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = React.useState(false);

  React.useEffect(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener?.("change", update);
    return () => query.removeEventListener?.("change", update);
  }, []);

  return reduced;
}

export interface AnimatedNumberProps extends Omit<
  React.ComponentProps<"span">,
  "children" | "ref"
> {
  /** The final figure. */
  value: number;
  /** Where the count starts. */
  from?: number;
  /** Length of the count-up in milliseconds. */
  duration?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  /** Fixed by default so the server and the client format identically. */
  locale?: string;
  /** Takes over formatting entirely when given. */
  format?: (value: number) => string;
}

function AnimatedNumber({
  className,
  value,
  from = 0,
  duration = 1400,
  decimals = 0,
  prefix = "",
  suffix = "",
  locale = "en-US",
  format,
  ...props
}: AnimatedNumberProps) {
  const reduced = usePrefersReducedMotion();
  const ref = React.useRef<HTMLSpanElement>(null);
  const [current, setCurrent] = React.useState(from);
  const [started, setStarted] = React.useState(false);

  useIsomorphicLayoutEffect(() => {
    const node = ref.current;
    if (!node) return;
    // No motion, or no observer to lean on: show the real figure at once.
    if (reduced || typeof IntersectionObserver === "undefined") {
      setCurrent(value);
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            setStarted(true);
            observer.disconnect();
          }
        }
      },
      { threshold: 0.35 },
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [reduced, value]);

  React.useEffect(() => {
    if (!started || reduced) return;
    let frame = 0;
    const startedAt = performance.now();
    const tick = (now: number) => {
      const progress = duration <= 0 ? 1 : Math.min(1, (now - startedAt) / duration);
      const eased = 1 - Math.pow(1 - progress, 3);
      setCurrent(from + (value - from) * eased);
      if (progress < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [started, reduced, value, from, duration]);

  const render = React.useCallback(
    (n: number) =>
      format
        ? format(n)
        : `${prefix}${n.toLocaleString(locale, {
            minimumFractionDigits: decimals,
            maximumFractionDigits: decimals,
          })}${suffix}`,
    [format, prefix, suffix, locale, decimals],
  );

  return (
    <span
      ref={ref}
      data-slot="animated-number"
      className={cn("tabular-nums", className)}
      {...props}
    >
      {/* The animated text churns, so assistive tech gets the settled figure. */}
      <span aria-hidden="true">{render(current)}</span>
      <span className="sr-only">{render(value)}</span>
    </span>
  );
}

