                          />
                          <div
                            data-slot="admin-dashboard-activity-body"
                            className="flex min-w-0 flex-col gap-0.5"
                          >
                            <p
                              data-slot="admin-dashboard-activity-message"
                              className="text-sm text-foreground"
                            >
                              {item.message}
                            </p>
                            <time
                              data-slot="admin-dashboard-activity-time"
                              dateTime={iso}
                              className="text-caption text-muted-foreground"
                            >
                              {text}
                            </time>
                          </div>
                        </li>
                      );
                    })}
                  </ol>
                )}
              </CardContent>
            </Card>
          </div>
        </div>

        {children}
      </div>
    </DashboardShell>
  );
}

export { AdminDashboard };

"use client";

/** Application shell: a collapsible sidebar driven by prop data, a sticky top bar with a trigger, breadcrumbs, search and a user menu, and the page in the inset. */
import * as React from "react";
import { LogOut, Settings, User } from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
} from "@/components/blocks/app-sidebar";
import { cn } from "@/lib/utils";
import { useT } from "@/lib/i18n";

export interface DashboardShellNavItem {
  /** Row label, also used as the collapsed-mode tooltip. */
  label: string;
  /** Glyph pinned at the inline start. */
  icon?: React.ReactNode;
  /** Renders the row as a link when set. */
  href?: string;
  /** Marks the row as the current page. */
  active?: boolean;
  disabled?: boolean;
  /** Counter or status pill at the inline end. Only shown while expanded. */
  badge?: React.ReactNode;
  onSelect?: () => void;
}

export interface DashboardShellNavGroup {
  /** Heading above the group. It folds away in collapsed mode. */
  label?: string;
  items: DashboardShellNavItem[];
}

export interface DashboardShellUser {
  name: string;
  email?: string;
  /** Avatar image source. Falls back to `initials`, then to the first letter of the name. */
  avatarSrc?: string;
  initials?: string;
}

export interface DashboardShellMenuItem {
  label: string;
  icon?: React.ReactNode;
  href?: string;
  destructive?: boolean;
  onSelect?: () => void;
}

export interface DashboardShellProps extends React.ComponentProps<"div"> {
  /** Sidebar navigation, grouped. */
  nav?: DashboardShellNavGroup[];
  /** Mark or wordmark in the sidebar header. */
  brand?: React.ReactNode;
  /** Extra content pinned to the bottom of the sidebar. */
  sidebarFooter?: React.ReactNode;
  /** Breadcrumb trail in the top bar, typically the Breadcrumb primitive. */
  breadcrumbs?: React.ReactNode;
  /** Search control in the top bar, typically an Input or the command palette trigger. */
  search?: React.ReactNode;
  /** Buttons between the search and the user menu. */
  actions?: React.ReactNode;
  /** Signed-in account. Omit it to hide the user menu. */
  user?: DashboardShellUser;
  /** Rows above the sign-out entry of the user menu. */
  userMenuItems?: DashboardShellMenuItem[];
  /** Text of the sign-out row. */
  signOutLabel?: string;
  onSignOut?: () => void;
  /** Accessible name of the sidebar landmark. */
  sidebarLabel?: string;
  /** Sidebar starts expanded unless this is false. */
  defaultSidebarOpen?: boolean;
  /** Controlled sidebar state. */
  sidebarOpen?: boolean;
  onSidebarOpenChange?: (open: boolean) => void;
  /** Extra classes for the scrolling content area. */
  contentClassName?: string;
}

const defaultMenuItems: DashboardShellMenuItem[] = [
  { label: "Profile", icon: <User aria-hidden="true" /> },
  { label: "Settings", icon: <Settings aria-hidden="true" /> },
];

function initialsOf(user: DashboardShellUser): string {
  if (user.initials) return user.initials;
  return user.name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("");
}

function DashboardShell({
  className,
  nav = [],
  brand,
  sidebarFooter,
  breadcrumbs,
  search,
  actions,
  user,
  userMenuItems = defaultMenuItems,
  signOutLabel: signOutLabelProp,
  onSignOut,
  sidebarLabel: sidebarLabelProp,
  defaultSidebarOpen = true,
  sidebarOpen,
  onSidebarOpenChange,
  contentClassName,
  children,
  ...props
}: DashboardShellProps) {
  const t = useT();
  const signOutLabel = signOutLabelProp ?? t("dashboardShell.signOut");
  const sidebarLabel = sidebarLabelProp ?? t("dashboardShell.sidebarLabel");
  return (
    <SidebarProvider
      data-slot="dashboard-shell"
      defaultOpen={defaultSidebarOpen}
      open={sidebarOpen}
      onOpenChange={onSidebarOpenChange}
      className={cn(className)}
      {...props}
    >
      <Sidebar label={sidebarLabel}>
        <SidebarHeader>
          <div
            data-slot="dashboard-shell-brand"
            className="flex min-w-0 items-center gap-2 px-1 [&_svg]:shrink-0"
          >
            {brand}
          </div>
        </SidebarHeader>

        <SidebarContent>
          {nav.map((group, groupIndex) => (
            <SidebarGroup key={group.label ?? groupIndex}>
              {group.label ? <SidebarGroupLabel>{group.label}</SidebarGroupLabel> : null}
              <SidebarMenu>
                {group.items.map((item) => (
                  <SidebarMenuItem key={item.label}>
                    {item.href ? (
                      // Slot takes exactly one child, so the link supplies its
                      // own icon and label rather than the `icon` prop.
                      <SidebarMenuButton
                        asChild
                        isActive={item.active}
                        tooltip={item.label}
                        aria-disabled={item.disabled || undefined}
                      >
                        <a href={item.href} onClick={item.onSelect}>
                          {item.icon ? (
                            <span aria-hidden="true" className="flex shrink-0">
                              {item.icon}
                            </span>
                          ) : null}
                          <span className="min-w-0 flex-1 truncate group-data-[state=collapsed]/sidebar:hidden">
                            {item.label}
                          </span>
                        </a>
                      </SidebarMenuButton>
                    ) : (
                      <SidebarMenuButton
                        icon={item.icon}
                        isActive={item.active}
                        tooltip={item.label}
                        disabled={item.disabled}
                        onClick={item.onSelect}
                      >
                        {item.label}
                      </SidebarMenuButton>
                    )}
                    {item.badge ? (
                      <span
                        data-slot="dashboard-shell-nav-badge"
                        className={cn(
                          "pointer-events-none absolute inset-y-0 end-2 my-auto flex h-5 items-center",
                          "rounded-badge bg-sidebar-accent px-1.5 text-caption font-semibold",
                          "text-sidebar-accent-foreground",
                          "group-data-[state=collapsed]/sidebar:hidden",
                        )}
                      >
                        {item.badge}
                      </span>
                    ) : null}
                  </SidebarMenuItem>
                ))}
              </SidebarMenu>
            </SidebarGroup>
          ))}
        </SidebarContent>

        {sidebarFooter ? <SidebarFooter>{sidebarFooter}</SidebarFooter> : null}
      </Sidebar>

      <SidebarInset>
        <header
          data-slot="dashboard-shell-topbar"
          className={cn(
            "sticky top-0 z-(--z-sticky) flex h-(--header-h) shrink-0 items-center gap-2",
            "border-b bg-background/80 px-(--gutter) backdrop-blur-sm",
          )}
        >
          <SidebarTrigger />

          {breadcrumbs ? (
            <div data-slot="dashboard-shell-breadcrumbs" className="ms-1 hidden min-w-0 md:block">
              {breadcrumbs}
            </div>
          ) : null}

          <div className="ms-auto flex min-w-0 items-center gap-2">
            {search ? (
              <div data-slot="dashboard-shell-search" className="min-w-0">
                {search}
              </div>
            ) : null}
            {actions}

            {user ? (
              <DropdownMenu>
                <DropdownMenuTrigger
                  data-slot="dashboard-shell-user-trigger"
                  aria-label={`Account menu for ${user.name}`}
                  className={cn(
                    "flex shrink-0 items-center gap-2 rounded-control p-1 outline-none",
                    "transition-colors duration-(--duration-fast) ease-standard",
                    "hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring",
                  )}
                >
                  <Avatar className="size-8">
                    {user.avatarSrc ? <AvatarImage src={user.avatarSrc} alt="" /> : null}
                    <AvatarFallback>{initialsOf(user)}</AvatarFallback>
                  </Avatar>
                </DropdownMenuTrigger>

                <DropdownMenuContent align="end" className="w-56">
                  <DropdownMenuLabel className="flex min-w-0 flex-col gap-0.5">
                    <span className="truncate font-semibold">{user.name}</span>
                    {user.email ? (
                      <span className="truncate text-caption font-normal text-muted-foreground">
                        {user.email}
                      </span>
                    ) : null}
                  </DropdownMenuLabel>
                  <DropdownMenuSeparator />

                  {userMenuItems.map((item) =>
                    item.href ? (
                      <DropdownMenuItem
                        key={item.label}
                        asChild
                        variant={item.destructive ? "destructive" : "default"}
                      >
                        <a href={item.href} onClick={item.onSelect}>
                          {item.icon}
                          {item.label}
                        </a>
                      </DropdownMenuItem>
                    ) : (
                      <DropdownMenuItem
                        key={item.label}
                        variant={item.destructive ? "destructive" : "default"}
                        onSelect={item.onSelect}
                      >
                        {item.icon}
                        {item.label}
                      </DropdownMenuItem>
                    ),
                  )}

                  {onSignOut ? (
                    <>
                      <DropdownMenuSeparator />
                      <DropdownMenuItem variant="destructive" onSelect={onSignOut}>
                        <LogOut aria-hidden="true" />
                        {signOutLabel}
                      </DropdownMenuItem>
                    </>
                  ) : null}
                </DropdownMenuContent>
              </DropdownMenu>
            ) : null}
          </div>
        </header>

        <div
          data-slot="dashboard-shell-content"
          className={cn("flex min-w-0 flex-1 flex-col gap-6 p-(--gutter)", contentClassName)}
        >
          {children}
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

export { DashboardShell };

"use client";

/** Full-page error screens: a 404 and a 500, both built on one shared layout with an oversized display code, a message and recovery actions. */
import * as React from "react";
import { ArrowLeft, House, RotateCw } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { useT } from "@/lib/i18n";

export interface ErrorPageProps extends Omit<React.ComponentProps<"div">, "title"> {
  /** Oversized display code, such as `404`. */
  code?: React.ReactNode;
  /** Small uppercase line above the heading. */
  eyebrow?: React.ReactNode;
  title?: React.ReactNode;
  description?: React.ReactNode;
  /** Text of the primary action. */
  homeLabel?: string;
  /** Destination of the primary action. Defaults to the site root. */
  homeHref?: string;
  onGoHome?: () => void;
  /** Text of the back action. Pass `showBack={false}` to drop it. */
  backLabel?: string;
  onGoBack?: () => void;
  showBack?: boolean;
  /** Retry action. Rendered only when `onRetry` is given. */
  retryLabel?: string;
  onRetry?: () => void;
  /** Reference shown under the actions, such as a request id. */
  reference?: React.ReactNode;
  /** Extra content under the actions. */
  children?: React.ReactNode;
}

/** Shared chrome for the error screens: layered backdrop, display code, copy and actions. */
function ErrorPageLayout({
  className,
  code,
  eyebrow,
  title,
  description,
  homeLabel: homeLabelProp,
  homeHref = "/",
  onGoHome,
  backLabel: backLabelProp,
  onGoBack,
  showBack = true,
  retryLabel: retryLabelProp,
  onRetry,
  reference,
  children,
  ...props
}: ErrorPageProps) {
  const t = useT();
  const homeLabel = homeLabelProp ?? t("errorPages.home");
  const backLabel = backLabelProp ?? t("errorPages.back");
  const retryLabel = retryLabelProp ?? t("errorPages.retry");

  return (
    <div
      data-slot="error-page"
      className={cn(
        "relative isolate flex min-h-svh w-full flex-col items-center justify-center overflow-hidden",
        "bg-background px-(--gutter) py-16 text-center",
        className,
      )}
      {...props}
    >
      <div
        aria-hidden="true"
        className={cn(
          "pointer-events-none absolute inset-0 z-(--z-below)",
          "[background-image:linear-gradient(to_right,color-mix(in_oklab,var(--foreground)_6%,transparent)_1px,transparent_1px),linear-gradient(to_bottom,color-mix(in_oklab,var(--foreground)_6%,transparent)_1px,transparent_1px)]",
          "[background-size:64px_64px]",
          "[mask-image:radial-gradient(65%_55%_at_50%_45%,black,transparent)]",
        )}
      />
      <div
        aria-hidden="true"
        className="pointer-events-none absolute start-1/2 top-1/3 z-(--z-below) size-[34rem] -translate-x-1/2 rounded-full bg-primary/15 blur-3xl rtl:translate-x-1/2"
      />

      <div className="flex max-w-xl flex-col items-center gap-6">
        {code ? (
          <p
            data-slot="error-page-code"
            className={cn(
              "font-display text-[clamp(6rem,22vw,13rem)] leading-none font-bold tracking-tighter",
              "bg-linear-to-b from-foreground to-foreground/25 bg-clip-text text-transparent",
              "tabular-nums select-none",
            )}
          >
            {code}
          </p>
        ) : null}

        {eyebrow ? (
          <p
            data-slot="error-page-eyebrow"
            className="text-eyebrow font-semibold text-primary uppercase"
          >
            {eyebrow}
          </p>
        ) : null}

        <h1 data-slot="error-page-title" className="font-display text-h2 text-balance uppercase">
          {title}
        </h1>

        {description ? (
          <p className="max-w-prose text-body-lg text-pretty text-muted-foreground">
            {description}
          </p>
        ) : null}

        <div
          data-slot="error-page-actions"
          className="mt-2 flex flex-wrap items-center justify-center gap-3"
        >
          {onRetry ? (
            <Button size="lg" onClick={onRetry}>
              <RotateCw aria-hidden="true" />
              {retryLabel}
            </Button>
          ) : null}

          {/* Slot takes exactly one child, so the link and the plain button are
              two separate branches rather than a conditional inside one. */}
          {onGoHome ? (
            <Button variant={onRetry ? "outline" : "default"} size="lg" onClick={onGoHome}>
              <House aria-hidden="true" />
              {homeLabel}
            </Button>
          ) : (
            <Button asChild variant={onRetry ? "outline" : "default"} size="lg">
              <a href={homeHref}>
                <House aria-hidden="true" />
                {homeLabel}
              </a>
            </Button>
          )}

          {showBack ? (
            <Button
              variant="ghost"
              size="lg"
              onClick={() => {
                if (onGoBack) {
                  onGoBack();
                  return;
                }
                if (typeof window !== "undefined") window.history.back();
              }}
            >
              <ArrowLeft aria-hidden="true" className="rtl:-scale-x-100" />
              {backLabel}
            </Button>
          ) : null}
        </div>

        {reference ? (
          <p data-slot="error-page-reference" className="text-caption text-muted-foreground">
            {reference}
          </p>
        ) : null}

        {children}
      </div>
    </div>
  );
}

/** Page shown when a route does not resolve. */
function NotFoundPage({
  code = "404",
  eyebrow: eyebrowProp,
  title: titleProp,
  description: descriptionProp,
  ...props
}: ErrorPageProps) {
  const t = useT();
  const eyebrow = eyebrowProp ?? t("errorPages.notFoundEyebrow");
  const title = titleProp ?? t("errorPages.notFoundTitle");
  const description = descriptionProp ?? t("errorPages.notFoundDescription");

  return (
    <ErrorPageLayout
      data-slot="not-found-page"
      code={code}
      eyebrow={eyebrow}
      title={title}
      description={description}
      {...props}
    />
  );
}

/** Page shown when the server fails, with a retry action alongside the usual escapes. */
function ServerErrorPage({
  code = "500",
  eyebrow: eyebrowProp,
  title: titleProp,
  description: descriptionProp,
  onRetry,
  ...props
}: ErrorPageProps) {
  const t = useT();
  const eyebrow = eyebrowProp ?? t("errorPages.serverErrorEyebrow");
  const title = titleProp ?? t("errorPages.serverErrorTitle");
  const description = descriptionProp ?? t("errorPages.serverErrorDescription");

  return (
    <ErrorPageLayout
      data-slot="server-error-page"
      code={code}
      eyebrow={eyebrow}
      title={title}
      description={description}
      onRetry={onRetry ?? (() => window.location.reload())}
      {...props}
    />
  );
}

export { NotFoundPage, ServerErrorPage, ErrorPageLayout };

"use client";

/** Password recovery page: an email field that, once sent, is replaced by a confirmation panel with a resend action. */
import * as React from "react";
import { ArrowLeft, MailCheck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";
import { useT } from "@/lib/i18n";

export interface ForgotPasswordProps extends Omit<
  React.ComponentProps<"div">,
  "onSubmit" | "title"
> {
  logo?: React.ReactNode;
  eyebrow?: React.ReactNode;
  title?: React.ReactNode;
  subtitle?: React.ReactNode;
  emailLabel?: string;
  emailPlaceholder?: string;
  submitLabel?: string;
  /** Heading of the confirmation panel. */
  sentTitle?: React.ReactNode;
  /**
   * Body of the confirmation panel. Given a function it receives the address the
   * link went to, so the copy can name it.
   */
  sentDescription?: React.ReactNode | ((email: string) => React.ReactNode);
  resendLabel?: string;
  /** Text of the link back to sign-in. */
  backLabel?: string;
  backHref?: string;
  onBack?: () => void;
  /** Blocks the form and spins the submit button. */
  loading?: boolean;
  /** Request failure. Announced as an alert and wired to the field through `aria-describedby`. */
  error?: React.ReactNode;
  /** Controlled success state. Left undefined, the template flips itself on submit. */
  sent?: boolean;
  defaultEmail?: string;
  /** Receives the address to send the reset link to. */
  onSubmit?: (email: string) => void;
  /** Called by the resend button. Defaults to `onSubmit` with the same address. */
  onResend?: (email: string) => void;
}

function ForgotPassword({
  className,
  logo,
  eyebrow: eyebrowProp,
  title: titleProp,
  subtitle: subtitleProp,
  emailLabel: emailLabelProp,
  emailPlaceholder: emailPlaceholderProp,
  submitLabel: submitLabelProp,
  sentTitle: sentTitleProp,
  sentDescription,
  resendLabel: resendLabelProp,
  backLabel: backLabelProp,
  backHref,
  onBack,
  loading = false,
  error,
  sent,
  defaultEmail = "",
  onSubmit,
  onResend,
  ...props
}: ForgotPasswordProps) {
  const t = useT();
  const eyebrow = eyebrowProp ?? t("forgotPassword.eyebrow");
  const title = titleProp ?? t("forgotPassword.title");
  const subtitle = subtitleProp ?? t("forgotPassword.subtitle");
  const emailLabel = emailLabelProp ?? t("forgotPassword.emailLabel");
  const emailPlaceholder = emailPlaceholderProp ?? t("forgotPassword.emailPlaceholder");
  const submitLabel = submitLabelProp ?? t("forgotPassword.submit");
  const sentTitle = sentTitleProp ?? t("forgotPassword.sentTitle");
  const resendLabel = resendLabelProp ?? t("forgotPassword.resend");
  const backLabel = backLabelProp ?? t("forgotPassword.back");
  const id = React.useId();
  const emailId = `${id}-email`;
  const errorId = `${id}-error`;

  const [email, setEmail] = React.useState(defaultEmail);
  const [selfSent, setSelfSent] = React.useState(false);

  const isSent = sent ?? selfSent;

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (loading) return;
    onSubmit?.(email);
    if (sent === undefined) setSelfSent(true);
  };

  const description =
    typeof sentDescription === "function" ? sentDescription(email) : sentDescription;

  const backClasses = cn(
    "inline-flex items-center gap-2 rounded-xs text-sm font-medium text-muted-foreground",
    "underline-offset-4 hover:text-foreground hover:underline",
    "outline-none focus-visible:ring-2 focus-visible:ring-ring",
  );

  return (
    <div
      data-slot="forgot-password"
      className={cn(
        "relative isolate flex min-h-svh w-full items-center justify-center overflow-hidden",
        "bg-background px-(--gutter) py-12",
        className,
      )}
      {...props}
    >
      <div
        aria-hidden="true"
        className="pointer-events-none absolute -bottom-40 start-[-8rem] z-(--z-below) size-[28rem] rounded-full bg-primary/15 blur-3xl"
      />

      <div className="flex w-full max-w-[400px] flex-col gap-8">
        {logo ? <div className="flex items-center gap-3">{logo}</div> : null}

        {isSent ? (
          <div
            data-slot="forgot-password-sent"
            role="status"
            aria-live="polite"
            className="flex flex-col gap-6"
          >
            <span
              aria-hidden="true"
              className={cn(
                "flex size-12 items-center justify-center rounded-md",
                "border border-success/30 bg-success/10 text-success",
                "[&_svg]:size-5",
              )}
            >
              <MailCheck />
            </span>

            <div className="flex flex-col gap-2">
              <h1
                data-slot="forgot-password-sent-title"
                className="font-display text-h2 text-balance uppercase"
              >
                {sentTitle}
              </h1>
              <p className="text-sm text-pretty text-muted-foreground">
                {description ?? (
                  <>
                    A reset link is on its way
                    {email ? (
                      <>
                        {" to "}
                        <span className="font-medium text-foreground">{email}</span>
                      </>
                    ) : null}
                    . It expires in 30 minutes.
                  </>
                )}
              </p>
            </div>

            <div className="flex flex-col gap-3">
              <Button
                data-slot="forgot-password-resend"
                type="button"
                variant="outline"
                size="lg"
                loading={loading}
                className="w-full"
                onClick={() => (onResend ?? onSubmit)?.(email)}
              >
                {resendLabel}
              </Button>

              {backHref ? (
                <a href={backHref} className={cn(backClasses, "justify-center")}>
                  <ArrowLeft aria-hidden="true" className="size-4 rtl:-scale-x-100" />
                  {backLabel}
                </a>
              ) : (
                <button
                  type="button"
                  onClick={onBack}
                  className={cn(backClasses, "justify-center")}
                >
                  <ArrowLeft aria-hidden="true" className="size-4 rtl:-scale-x-100" />
                  {backLabel}
                </button>
              )}
            </div>
          </div>
        ) : (
          <>
            <header className="flex flex-col gap-2">
              {eyebrow ? (
                <p
                  data-slot="forgot-password-eyebrow"
                  className="text-eyebrow font-semibold text-primary uppercase"
                >
                  {eyebrow}
                </p>
              ) : null}
              <h1
                data-slot="forgot-password-title"
                className="font-display text-h2 text-balance uppercase"
              >
                {title}
              </h1>
              {subtitle ? (
                <p className="text-sm text-pretty text-muted-foreground">{subtitle}</p>
              ) : null}
            </header>

            <form data-slot="forgot-password-form" noValidate onSubmit={handleSubmit}>
              <div className="flex flex-col gap-5">
                {error ? (
                  <p
                    id={errorId}
                    role="alert"
                    data-slot="forgot-password-error"
                    className={cn(
                      "rounded-input border border-destructive/40 bg-destructive/10 px-3 py-2",
                      "text-sm font-medium text-destructive",
                    )}
                  >
                    {error}
                  </p>
                ) : null}

                <div className="grid gap-2">
                  <Label htmlFor={emailId}>{emailLabel}</Label>
                  <Input
                    id={emailId}
                    name="email"
                    type="email"
                    autoComplete="email"
                    inputMode="email"
                    required
                    placeholder={emailPlaceholder}
                    value={email}
                    disabled={loading}
                    aria-invalid={error ? true : undefined}
                    aria-describedby={error ? errorId : undefined}
                    onChange={(event) => setEmail(event.target.value)}
                  />
                </div>

                <Button type="submit" size="lg" loading={loading} className="w-full">
                  {submitLabel}
                </Button>
              </div>
            </form>

            {backHref ? (
              <a href={backHref} className={backClasses}>
                <ArrowLeft aria-hidden="true" className="size-4 rtl:-scale-x-100" />
                {backLabel}
              </a>
            ) : (
              <button type="button" onClick={onBack} className={cn(backClasses, "self-start")}>
                <ArrowLeft aria-hidden="true" className="size-4 rtl:-scale-x-100" />
                {backLabel}
              </button>
            )}
          </>
        )}
      </div>
    </div>
  );
}

export { ForgotPassword };

