"use client";

/** Writes text to the clipboard and reports success for a couple of seconds, falling back to a detached textarea where the async API is blocked. */
import * as React from "react";

export interface UseClipboardOptions {
  /** How long `copied` stays true, in milliseconds. */
  timeout?: number;
  /** Called with the text that reached the clipboard. */
  onCopy?: (value: string) => void;
  /** Called when the clipboard refused the write. */
  onError?: (error: Error) => void;
}

export interface UseClipboardResult {
  /** Writes `value`, resolving to whether it landed. Never throws. */
  copy: (value: string) => Promise<boolean>;
  /** True from a successful copy until `timeout` elapses. */
  copied: boolean;
  /** The last failure, or null. */
  error: Error | null;
  /** Clear `copied` and `error` before the timeout runs out. */
  reset: () => void;
}

/**
 * Legacy path for insecure origins, older Safari and permission-denied states.
 * Selects a detached textarea, copies, then restores whatever the user had
 * selected so the page does not visibly lose its selection.
 */
function copyWithExecCommand(value: string): boolean {
  if (typeof document === "undefined" || typeof document.execCommand !== "function") return false;

  const area = document.createElement("textarea");
  area.value = value;
  area.setAttribute("readonly", "");
  area.style.position = "fixed";
  area.style.opacity = "0";
  area.style.pointerEvents = "none";
  document.body.appendChild(area);

  const selection = document.getSelection();
  const previous = selection && selection.rangeCount > 0 ? selection.getRangeAt(0) : null;

  let ok = false;
  try {
    area.select();
    ok = document.execCommand("copy");
  } catch {
    ok = false;
  }

  area.remove();
  if (selection && previous) {
    selection.removeAllRanges();
    selection.addRange(previous);
  }
  return ok;
}

/**
 * Clipboard state for any "copy this" affordance.
 *
 * The component owns the markup; this owns the write, the success window and
 * the failure. `copy` resolves to a boolean instead of throwing, so a caller
 * can branch on it without a try/catch at every call site.
 */
export function useClipboard({
  timeout = 2000,
  onCopy,
  onError,
}: UseClipboardOptions = {}): UseClipboardResult {
  const [copied, setCopied] = React.useState(false);
  const [error, setError] = React.useState<Error | null>(null);
  const timer = React.useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const mounted = React.useRef(true);

  // Callbacks are read through a ref so `copy` stays referentially stable even
  // when the caller passes inline arrow functions, which is the common case.
  const handlers = React.useRef({ onCopy, onError });
  handlers.current = { onCopy, onError };

  React.useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      clearTimeout(timer.current);
    };
  }, []);

  const reset = React.useCallback(() => {
    clearTimeout(timer.current);
    setCopied(false);
    setError(null);
  }, []);

  const copy = React.useCallback(
    async (value: string) => {
      let ok = false;
      try {
        if (typeof navigator !== "undefined" && navigator.clipboard?.writeText) {
          await navigator.clipboard.writeText(value);
          ok = true;
        } else {
          ok = copyWithExecCommand(value);
        }
      } catch {
        ok = copyWithExecCommand(value);
      }

      if (!mounted.current) return ok;

      if (!ok) {
        const failure = new Error("Clipboard write was refused by the browser.");
        setCopied(false);
        setError(failure);
        handlers.current.onError?.(failure);
        return false;
      }

      setError(null);
      setCopied(true);
      handlers.current.onCopy?.(value);
      clearTimeout(timer.current);
      timer.current = setTimeout(() => {
        if (mounted.current) setCopied(false);
      }, timeout);
      return true;
    },
    [timeout],
  );

  return { copy, copied, error, reset };
}

"use client";

/** Language and writing direction for the whole document: writes `lang` and `dir` on `<html>`, remembers the choice, and keeps every tab in step. */
import * as React from "react";

export type Direction = "ltr" | "rtl";

export interface LocaleOption {
  /** BCP 47 tag written to `<html lang>`, e.g. `en`, `ar`, `pt-BR`. */
  code: string;
  /** The language's name in itself — what a speaker of it scans the list for. */
  nativeName: string;
  /** The same name in English, shown as a second line for everyone else. */
  englishName?: string;
  /** Overrides the direction derived from `code`. */
  dir?: Direction;
}

/**
 * The four the library ships message catalogues, fonts and tests for. Pass your
 * own list to override; `useLocale` keeps working for any language, it simply
 * has no translated strings of its own beyond these.
 */
export const DEFAULT_LOCALES: readonly LocaleOption[] = [
  { code: "en", nativeName: "English", englishName: "English", dir: "ltr" },
  { code: "ar", nativeName: "العربية", englishName: "Arabic", dir: "rtl" },
  { code: "fr", nativeName: "Français", englishName: "French", dir: "ltr" },
  { code: "hi", nativeName: "हिन्दी", englishName: "Hindi", dir: "ltr" },
];

/** Shared with the pre-paint script, so the first frame and React never disagree. */
export const LOCALE_STORAGE_KEY = "design-eg:locale";

/**
 * Right-to-left primary language subtags. `Intl.Locale` can answer this in
 * newer engines but not in every browser the library supports, and the list of
 * RTL scripts is short enough to carry.
 */
const RTL_LANGUAGES = new Set([
  "ar",
  "arc",
  "ckb",
  "dv",
  "fa",
  "he",
  "khw",
  "ks",
  "ku",
  "ps",
  "sd",
  "syr",
  "ug",
  "ur",
  "yi",
]);

/** The direction a locale is written in, from its own `dir` or from its language subtag. */
export function directionOf(locale: LocaleOption | string): Direction {
  if (typeof locale !== "string") return locale.dir ?? directionOf(locale.code);
  const language = locale.toLowerCase().split(/[-_]/)[0] ?? "";
  return RTL_LANGUAGES.has(language) ? "rtl" : "ltr";
}

/**
 * Writes the locale onto `<html>`. Setting `lang` is what switches the Arabic
 * font stack and line-height in the base layer; setting `dir` is what every
 * logical property in the library mirrors against.
 */
export function applyLocale(locale: LocaleOption | string): Direction {
  const root = document.documentElement;
  const dir = directionOf(locale);
  root.lang = typeof locale === "string" ? locale : locale.code;
  root.dir = dir;
  return dir;
}

/** Same reason as use-theme: `storage` never fires in the tab that wrote it. */
const listeners = new Set<() => void>();

function emit() {
  for (const listener of [...listeners]) listener();
}

function subscribe(onChange: () => void) {
  listeners.add(onChange);
  window.addEventListener("storage", onChange);
  return () => {
    listeners.delete(onChange);
    window.removeEventListener("storage", onChange);
  };
}

function readLocale(storageKey: string, codes: string[], fallback: string): string {
  try {
    const saved = window.localStorage.getItem(storageKey);
    if (saved !== null && codes.includes(saved)) return saved;
  } catch {
    // Storage can be disabled outright; fall back to what the document says.
  }
  const current = document.documentElement.lang;
  return codes.includes(current) ? current : fallback;
}

export interface UseLocaleOptions {
  /** The languages to offer, in the order a picker should list them. */
  locales?: readonly LocaleOption[];
  /**
   * Controlled locale, which wins over the stored preference.
   *
   * For an app where the language is part of the URL — the usual shape in
   * Next.js — the route is the truth, and a stale stored value must not be
   * allowed to override the page that was actually served: the first client
   * render would otherwise flip `lang` and the font stack away from the markup
   * the server sent.
   */
  locale?: string;
  /** Used for the server render, and until the reader has chosen. Defaults to the first locale. */
  defaultLocale?: string;
  /** localStorage key holding the choice. Must match the pre-paint script's. */
  storageKey?: string;
}

export interface UseLocaleResult {
  /** The active BCP 47 tag. */
  locale: string;
  /** The full entry for `locale`, for rendering its name. */
  option: LocaleOption;
  locales: readonly LocaleOption[];
  /** The active direction, already applied to `<html dir>`. */
  dir: Direction;
  /** Ignores a code that is not in `locales`, so a stale value cannot strand the UI. */
  setLocale: (code: string) => void;
  /** False on the server and during hydration. See `useTheme` for why. */
  mounted: boolean;
}

/**
 * Reads and writes the document's language.
 *
 * Like `useTheme`, the document is the source of truth rather than a React
 * context, so this drops into any app. It deliberately does not touch routing
 * or message catalogues: wire the picker's `onLocaleChange` to your i18n
 * framework, and this keeps `lang`, `dir` and the stored preference correct
 * underneath it.
 */
export function useLocale(options: UseLocaleOptions = {}): UseLocaleResult {
  const {
    locales = DEFAULT_LOCALES,
    locale: controlledLocale,
    defaultLocale = locales[0]?.code ?? "en",
    storageKey = LOCALE_STORAGE_KEY,
  } = options;

  // `locales` is an inline literal at most call sites, so its identity changes
  // on every render. Deriving the codes as one string gives the snapshot a
  // dependency that only changes when the list really does.
  const codes = locales.map((locale) => locale.code).join(" ");
  const getSnapshot = React.useCallback(
    () => readLocale(storageKey, codes.split(" "), defaultLocale),
    [storageKey, codes, defaultLocale],
  );

  const stored = React.useSyncExternalStore(subscribe, getSnapshot, () => defaultLocale);
  const locale = controlledLocale ?? stored;
  const mounted = React.useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );

  const option = locales.find((entry) => entry.code === locale) ??
    locales[0] ?? { code: locale, nativeName: locale };
  const dir = directionOf(option);

  // Mirrors applyLocale, but over the two primitives, so an inline `locales`
  // array cannot make this run on every render.
  React.useEffect(() => {
    if (!mounted) return;
    const root = document.documentElement;
    root.lang = locale;
    root.dir = dir;
  }, [mounted, locale, dir]);

  function setLocale(code: string) {
    const next = locales.find((entry) => entry.code === code);
    if (!next) return;
    try {
      window.localStorage.setItem(storageKey, next.code);
    } catch {
      // Nothing to do: the choice simply will not survive a reload.
    }
    applyLocale(next);
    emit();
  }

  return { locale, option, locales, dir, setLocale, mounted };
}

"use client";

/** Colour-mode state for the whole document: light, dark, or follow the system. Persists the choice, keeps every tab in step, and reacts when the OS preference flips. */
import * as React from "react";

/** What the reader picked. `system` keeps following the OS as it changes. */
export type Theme = "light" | "dark" | "system";

/** What is actually on screen once `system` has been resolved. */
export type ResolvedTheme = "light" | "dark";

/** The three choices, in the order a picker should list them. */
export const THEMES: readonly Theme[] = ["light", "dark", "system"];

/** Shared with the pre-paint script, so the first frame and React never disagree. */
export const THEME_STORAGE_KEY = "design-eg:theme";

const DARK_QUERY = "(prefers-color-scheme: dark)";

/**
 * `storage` only fires in *other* tabs, so a change made here needs its own
 * channel to reach the other hooks mounted on this page.
 */
const listeners = new Set<() => void>();

function isTheme(value: unknown): value is Theme {
  return value === "light" || value === "dark" || value === "system";
}

function prefersDark(): boolean {
  return typeof window.matchMedia === "function" && window.matchMedia(DARK_QUERY).matches;
}

/** What `theme` means for the pixels on screen right now. */
export function resolveTheme(theme: Theme): ResolvedTheme {
  if (theme !== "system") return theme;
  return prefersDark() ? "dark" : "light";
}

/**
 * Writes the mode onto `<html>`: the class and `data-theme` the token layer
 * selects on, `color-scheme` so scrollbars and native controls follow, and
 * `data-theme-choice` so a picker can tell "dark" from "system, which is dark".
 */
export function applyTheme(theme: Theme): ResolvedTheme {
  const root = document.documentElement;
  const resolved = resolveTheme(theme);
  root.classList.toggle("dark", resolved === "dark");
  root.classList.toggle("light", resolved === "light");
  root.dataset.theme = resolved;
  root.dataset.themeChoice = theme;
  root.style.colorScheme = resolved;
  return resolved;
}

function readTheme(storageKey: string): Theme {
  try {
    const saved = window.localStorage.getItem(storageKey);
    if (isTheme(saved)) return saved;
  } catch {
    // Storage can be disabled outright; fall back to what the document says.
  }
  const choice = document.documentElement.dataset.themeChoice;
  return isTheme(choice) ? choice : "system";
}

function subscribe(onChange: () => void) {
  listeners.add(onChange);
  const media = typeof window.matchMedia === "function" ? window.matchMedia(DARK_QUERY) : null;
  media?.addEventListener?.("change", onChange);
  window.addEventListener("storage", onChange);
  return () => {
    listeners.delete(onChange);
    media?.removeEventListener?.("change", onChange);
    window.removeEventListener("storage", onChange);
  };
}

function emit() {
  for (const listener of [...listeners]) listener();
}

export interface UseThemeOptions {
  /** Used for the server render, and until the reader has chosen. */
  defaultTheme?: Theme;
  /** localStorage key holding the choice. Must match the pre-paint script's. */
  storageKey?: string;
}

export interface UseThemeResult {
  /** The choice, which may be `system`. */
  theme: Theme;
  /** The choice with `system` resolved — always `light` or `dark`. */
  resolvedTheme: ResolvedTheme;
  setTheme: (theme: Theme) => void;
  /** Flips to whichever of light and dark is not currently showing. */
  toggleTheme: () => void;
  themes: readonly Theme[];
  /**
   * False on the server and during hydration. Render the neutral default while
   * it is false: reading storage during the first render makes the server and
   * the client disagree, and React throws the markup away.
   */
  mounted: boolean;
}

/**
 * Reads and writes the document's colour mode.
 *
 * The document is the single source of truth rather than a React context, so
 * this works in any app — with or without a provider, and alongside a pre-paint
 * script that has already set the class before React boots.
 */
export function useTheme(options: UseThemeOptions = {}): UseThemeResult {
  const { defaultTheme = "system", storageKey = THEME_STORAGE_KEY } = options;

  // Three separate stores rather than one object: each snapshot returns a
  // primitive, so useSyncExternalStore's identity check never loops.
  const theme = React.useSyncExternalStore(
    subscribe,
    () => readTheme(storageKey),
    () => defaultTheme,
  );
  const resolvedTheme = React.useSyncExternalStore(
    subscribe,
    () => resolveTheme(readTheme(storageKey)),
    () => (defaultTheme === "dark" ? "dark" : "light"),
  );
  const mounted = React.useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );

  // Keeps the document in step, including when `system` flips underneath us:
  // the choice is unchanged there, but the resolved mode is not.
  React.useEffect(() => {
    if (!mounted) return;
    applyTheme(theme);
  }, [mounted, theme, resolvedTheme]);

  const setTheme = React.useCallback(
    (next: Theme) => {
      try {
        window.localStorage.setItem(storageKey, next);
      } catch {
        // Nothing to do: the choice simply will not survive a reload.
      }
      applyTheme(next);
      emit();
    },
    [storageKey],
  );

  const toggleTheme = React.useCallback(() => {
    setTheme(resolvedTheme === "dark" ? "light" : "dark");
  }, [resolvedTheme, setTheme]);

  return { theme, resolvedTheme, setTheme, toggleTheme, themes: THEMES, mounted };
}
